INSERT INTO `users` (`id`, `username`, `email`, `password_hash`, `full_name`, `role`, `created_at`) VALUES
(1, 'admin', 'vlxdhoangyenqt@gmail.com', '$2a$10$iMoJ6VH758woiAIvIzhNPezooSMozpOJ/mDvF.vvNYuQZndvhUUmm', 'Quản Trị Viên Hoàng Yến', 'admin', '2026-09-15 18:16:18');
INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `group_type`, `description`, `image_url`, `seo_title`, `seo_description`, `sort_order`, `is_active`, `h1`, `content`, `created_at`, `updated_at`) VALUES
(1, NULL, 'XI MĂNG', 'xi-mang', 'vlxd', 'Xi măng xây tô PCB30, xi măng đa dụng và xi măng đổ bê tông kết cấu PCB40 phục vụ công trình tại Quảng Trị.', '/images/danh-muc/ximang.png', 'Xi Măng Xây Dựng Tại Quảng Trị | Báo Giá Xi Măng - Hoàng Yến', 'Mua xi măng xây dựng tại Quảng Trị. Tham khảo các loại xi măng dùng xây tô, đổ bê tông và thi công công trình. Liên hệ VLXD Hoàng Yến để nhận báo giá.', 1, 1, 'Xi Măng Xây Dựng Chính Hãng Tại Quảng Trị', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(2, NULL, 'THÉP XÂY DỰNG', 'thep-xay-dung', 'vlxd', 'Thép xây dựng Hòa Phát gồm thép cuộn D6, D8, thép cây vằn D10 - D25 mác CB300-V, CB400-V chuẩn barem tiêu chuẩn tại Quảng Trị.', '/images/danh-muc/thep.png', 'Thép Xây Dựng Tại Quảng Trị | Thép Hòa Phát Báo Giá - Hoàng Yến', 'Cung cấp thép xây dựng Hòa Phát tại Quảng Trị. Thép cuộn D6, D8, thép cây D10 - D25 chuẩn barem. Liên hệ VLXD Hoàng Yến để nhận báo giá.', 2, 1, 'THÉP XÂY DỰNG', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(3, NULL, 'TÔN', 'ton', 'vlxd', 'Tôn lạnh màu, tôn mạ kẽm Đông Á dập sóng vuông 5 sóng, 9 sóng, sóng ngói Ruby độ dày 0.35mm - 0.50mm, cách nhiệt và chống nóng hiệu quả.', '/images/danh-muc/ton.png', 'Tôn Lợp Mái Tại Quảng Trị | Tôn Đông Á Báo Giá - Hoàng Yến', 'Cung cấp tôn lợp mái, tôn lạnh mạ màu Đông Á tại Quảng Trị. Cán dập sóng 5 sóng, 9 sóng, sóng ngói theo kích thước yêu cầu.', 3, 1, 'TÔN', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(4, NULL, 'LƯỚI XÂY DỰNG', 'luoi-xay-dung', 'vlxd', 'Lưới B40 mạ kẽm sợi 2.7mm - 3.5mm, mắt lưới 50x50mm, 60x60mm đan chắc chắn, các khổ cao 1.0m đến 2.4m làm hàng rào và che chắn công trình.', '/images/danh-muc/b40.png', 'Lưới B40 Xây Dựng Tại Quảng Trị | Lưới Mạ Kẽm - Hoàng Yến', 'Cung cấp lưới B40 mạ kẽm các khổ từ 1.0m đến 2.4m tại Quảng Trị. Bán theo kg hoặc mét dài theo nhu cầu công trình.', 4, 1, 'LƯỚI XÂY DỰNG', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(5, NULL, 'GẠCH TUYNEL', 'gach-tuynel', 'vlxd', 'Gạch Tuynel đất sét nung 6 lỗ, 2 lỗ và gạch đặc công nghệ lò tuynel. Độ cứng cao, màu đỏ tươi đồng đều, chịu lực tốt cho công trình.', '/images/danh-muc/gach.png', 'Gạch Tuynel Đất Nung Tại Quảng Trị | Gạch 6 Lỗ, 2 Lỗ - Hoàng Yến', 'Cung cấp gạch tuynel 6 lỗ, 2 lỗ đất nung tại Đông Hà, Quảng Trị. Giao hàng tận công trình theo tiến độ thi công.', 5, 1, 'GẠCH TUYNEL', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(6, NULL, 'XÀ GỒ', 'xa-go', 'vlxd', 'Xà gồ thép chữ C, chữ Z mạ kẽm quy cách C100, C125, C150, C180, C200 độ dày 1.4mm - 2.5mm chịu lực vượt nhịp cho khung kèo mái lợp.', '/images/danh-muc/xago.png', 'Xà Gồ Thép C Mạ Kẽm Tại Quảng Trị | Xà Gồ C100 - C200 - Hoàng Yến', 'Cung cấp xà gồ thép C, xà gồ Z mạ kẽm tại Quảng Trị. Cắt theo khẩu độ mái và hỗ trợ đột lỗ theo bản vẽ thiết kế.', 6, 1, 'XÀ GỒ', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(7, NULL, 'XỐP - NHỰA', 'xop-nhua', 'vlxd', 'Tấm xốp cách nhiệt EPS tỷ trọng cao chống nóng mái tôn, chống ồn trần nhà, lót sàn bê tông nhẹ và cách âm phòng tại Quảng Trị.', '/images/danh-muc/xopnhua.png', 'Tấm Xốp Cách Nhiệt EPS Tại Quảng Trị | Xốp Chống Nóng - Hoàng Yến', 'Cung cấp tấm xốp EPS cách nhiệt chống nóng mái tôn tại Đông Hà, Quảng Trị. Đủ độ dày 2cm, 3cm, 5cm, 10cm giao tận nơi.', 7, 1, 'XỐP - NHỰA', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(8, NULL, 'KẼM BUỘC', 'kem-buoc', 'vlxd', 'Dây kẽm đen 1 ly dẻo dai, dễ uốn siết kết cấu sắt thép sàn móng dầm bê tông, không bị đứt gãy khi xoắn siết bằng móc buộc.', '/images/danh-muc/kem.png', 'Dây Kẽm Buộc 1 Ly Tại Quảng Trị | Kẽm Dẻo Xây Dựng - Hoàng Yến', 'Cung cấp kẽm buộc 1 ly dẻo dai cho thợ sắt và nhà thầu tại Đông Hà, Quảng Trị. Bán sỉ theo cuộn và bán lẻ theo kg.', 8, 1, 'KẼM BUỘC', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(9, NULL, 'ĐINH VÍT', 'dinh-vit', 'vlxd', 'Đinh thép đóng gỗ ghép cốp pha các cỡ 3 phân đến 10 phân, đinh bê tông tôi cứng và vít bắn tôn tự khoan đệm ron cao su chống dột.', '/images/danh-muc/dinhsat.png', 'Đinh Thép & Vít Bắn Tôn Tại Quảng Trị | Phụ Kiện Xây Dựng - Hoàng Yến', 'Cung cấp đinh thép đóng cốp pha, đinh bê tông và vít bắn tôn tự khoan có đệm ron cao su tại Đông Hà, Quảng Trị.', 9, 1, 'ĐINH VÍT', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(10, NULL, 'BỒN CẦU', 'bon-cau', 'noi-that', 'Bồn cầu một khối, bồn cầu hai khối thương hiệu Caesar, Viglacera, Mowoen. Men sứ chống bám bẩn, hệ thống xả xoáy hút đẩy mạnh mẽ, tiết kiệm nước.', '/images/danh-muc/boncau.png', 'Bồn Cầu Vệ Sinh Tại Quảng Trị | Bồn Cầu 1 Khối, 2 Khối - Hoàng Yến', 'Cung cấp bồn cầu một khối, bồn cầu hai khối Caesar tại Đông Hà, Quảng Trị. Men sứ sáng bóng, xả xoáy êm ái.', 10, 1, 'BỒN CẦU', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(11, NULL, 'LAVABO', 'lavabo', 'noi-that', 'Chậu rửa mặt Lavabo đặt bàn, âm bàn, treo tường men sứ trắng sáng, chống bám bẩn, thiết kế thanh lịch cho phòng tắm gia đình và công trình.', '/images/danh-muc/lavabo.png', 'Chậu Rửa Mặt Lavabo Tại Quảng Trị | Lavabo Đặt Bàn, Âm Bàn - Hoàng Yến', 'Cung cấp chậu rửa mặt lavabo đặt bàn đá, lavabo âm bàn tại Đông Hà, Quảng Trị. Đa dạng kiểu dáng vuông, tròn, oval.', 11, 1, 'LAVABO', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(12, NULL, 'VÒI HOA SEN', 'voi-hoa-sen', 'noi-that', 'Sen cây tắm đứng nóng lạnh, củ sen tắm massage bằng đồng thau mạ crom/niken hoặc inox 304, áp lực nước êm ái, điều chỉnh nhiệt độ mượt mà.', '/images/danh-muc/voi-hoa-sen.png', 'Sen Vòi Phòng Tắm Tại Quảng Trị | Sen Cây Nóng Lạnh - Hoàng Yến', 'Cung cấp sen cây tắm đứng, vòi sen nóng lạnh cao cấp tại Đông Hà, Quảng Trị. Thân đồng mạ crom sáng bóng, van ceramic bền bỉ.', 12, 1, 'VÒI HOA SEN', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(13, NULL, 'BỒN TẮM', 'bon-tam', 'noi-that', 'Bồn tắm nằm ngâm, bồn tắm Acrylic cao cấp thương hiệu Mowoen, Caesar thiết kế công thái học, giữ nhiệt lâu, chống trơn trượt an toàn.', '/images/danh-muc/bon-tam.png', 'Bồn Tắm Nằm Massage Tại Quảng Trị | Bồn Tắm Ngâm Acrylic - Hoàng Yến', 'Cung cấp bồn tắm ngâm đặt sàn, bồn tắm massage Acrylic tại Quảng Trị. Đủ kích thước 1m4 đến 1m8 cho phòng tắm gia đình.', 13, 1, 'BỒN TẮM', NULL, '2026-09-15 18:34:39', '2026-09-16 06:15:59'),
(14, NULL, 'GẠCH MEN', 'gach-men', 'noi-that', 'Gạch men ốp lát kích thước 30x30, 40x40, 30x60, 60x60, 80x80 cm men bóng kiếng, men mờ chống trơn, gạch giả gỗ cho phòng khách, phòng ngủ và nhà tắm.', '/images/danh-muc/gachmen.png', 'Gạch Men Ốp Lát Tại Quảng Trị | Gạch Lát Nền, Ốp Tường - Hoàng Yến', 'Cung cấp gạch men lát nền, gạch ốp tường 30x60, 60x60, 80x80 tại Đông Hà, Quảng Trị. Đa dạng mẫu mã, men bóng kiếng và men mờ.', 14, 1, 'GẠCH MEN', NULL, '2026-09-15 18:56:26', '2026-09-16 06:15:59');
