(1, 'Thép Hòa Phát', 'hoa-phat', 'Tập đoàn Hòa Phát - Nhà sản xuất thép xây dựng hàng đầu Việt Nam.', NULL, NULL, '/images/brands/hoa-phat.png', NULL, NULL, NULL, 1, '2026-09-15 18:34:43', '2026-09-16 06:15:59'),
(2, 'Xi Măng Sông Gianh', 'song-gianh', 'Xi măng Sông Gianh - Dòng xi măng bền sunfat chuyên dụng chống chọi khí hậu miền Trung.', NULL, NULL, '/images/brands/song-gianh.png', NULL, NULL, NULL, 1, '2026-09-15 18:34:43', '2026-09-16 06:15:59'),
(3, 'Xi Măng Bỉm Sơn', 'bim-son', 'Xi măng Bỉm Sơn (Vicem Bỉm Sơn) - Thương hiệu xi măng Con Voi chất lượng cao cho kết cấu chịu lực.', NULL, NULL, '/images/brands/bim-son.png', NULL, NULL, NULL, 0, '2026-09-15 18:34:43', '2026-09-16 06:15:59'),
(4, 'Xi Măng Nghi Sơn', 'nghi-son', 'Xi măng Nghi Sơn - Liên doanh công nghệ Nhật Bản, độ dẻo cao và phát triển cường độ sớm.', NULL, NULL, '/images/brands/nghi-son.png', NULL, NULL, NULL, 0, '2026-09-15 18:34:43', '2026-09-16 06:15:59'),
(5, 'Thép TISCO', 'tisco', 'Thép TISCO - Công ty Cổ phần Gang Thép Thái Nguyên, thương hiệu thép xây dựng uy tín lâu đời.', NULL, NULL, '/images/brands/tisco.png', NULL, NULL, NULL, 1, '2026-09-15 18:34:43', '2026-09-16 06:15:59'),
(6, 'Tôn Đông Á', 'ton-dong-a', 'Tôn Đông Á - Nhà sản xuất thép lá mạ kẽm, tôn lạnh mạ màu chất lượng cao.', NULL, NULL, '/images/brands/ton-dong-a.png', NULL, NULL, NULL, 1, '2026-09-15 18:34:43', '2026-09-16 06:15:59'),
(7, 'Tôn Hoa Sen', 'hoa-sen', 'Tập đoàn Hoa Sen - Thương hiệu tôn mạ hàng đầu Việt Nam.', NULL, NULL, '/images/brands/hoa-sen.png', NULL, NULL, NULL, 0, '2026-09-15 18:34:43', '2026-09-16 06:15:59'),
(8, 'Caesar', 'caesar', 'Thiết bị vệ sinh CAESAR - Thương hiệu thiết bị phòng tắm sứ men Nano cao cấp.', NULL, NULL, '/images/brands/caesar.png', NULL, NULL, NULL, 0, '2026-09-15 18:34:43', '2026-09-16 06:15:59'),
(9, 'Mowoen', 'mowoen', 'Thiết bị phòng tắm cao cấp Mowoen - Công nghệ chuẩn châu Âu.', NULL, NULL, '/images/brands/mowoen.png', NULL, NULL, NULL, 0, '2026-09-15 18:34:43', '2026-09-16 06:15:59'),
(10, 'Vicem Hà Tiên', 'vicem-ha-tien', 'Xi măng Vicem Hà Tiên - Thương hiệu xi măng biểu tượng Kỳ Lân chất lượng cao.', NULL, NULL, '/images/brands/vicem-ha-tien.png', NULL, NULL, NULL, 1, '2026-09-15 18:34:43', '2026-09-16 06:15:59'),
(11, 'Xi Măng Công Thanh', 'cong-thanh', 'Xi măng Công Thanh - Thương hiệu xi măng chất lượng cao được ưa chuộng tại miền Trung.', NULL, NULL, '/images/brands/cong-thanh.png', NULL, NULL, NULL, 1, '2026-09-15 18:34:43', '2026-09-16 06:15:59');
