(1304, NULL, 'XI MĂNG SG', 'xi-mang-song-gianh', '', '0', '0', 'Bao', '', '', NULL, NULL, '/images/uploads/1789502537964-anh-sanpham-copy-2-.png', 'XI MĂNG SG', '', 0, 1, 'published', '2026-09-15 19:59:52', '2026-09-15 20:02:26'),
(1305, 3, 'Xi Măng Bỉm Sơn PCB40 Con Voi (Quy cách #1)', 'xi-mang-bim-son-pcb40-item-1', 'BS-PCB40-001', '85000', '93500', 'Bao', 'Mô tả sản phẩm Xi Măng Bỉm Sơn PCB40 Con Voi (Quy cách #1) phân phối chính hãng tại Siêu thị VLXD Hoàng Yến Quảng Trị.', 'Nội dung chi tiết thông số kỹ thuật sản phẩm Xi Măng Bỉm Sơn PCB40 Con Voi (Quy cách #1).', NULL, NULL, '/anh-sanpham.png', 'Xi Măng Bỉm Sơn PCB40 Con Voi (Quy cách #1)', 'Báo giá sản phẩm Xi Măng Bỉm Sơn PCB40 Con Voi (Quy cách #1) tại Quảng Trị.', 0, 1, 'published', '2026-09-15 20:01:23', '2026-09-15 20:39:37'),
(1306, 4, 'Xi Măng Nghi Sơn PCB40 Mác Cao (Quy cách #2)', 'xi-mang-nghi-son-pcb40-item-2', 'NS-PCB40-002', '88000', '96800', 'Bao', 'Mô tả sản phẩm Xi Măng Nghi Sơn PCB40 Mác Cao (Quy cách #2) phân phối chính hãng tại Siêu thị VLXD Hoàng Yến Quảng Trị.', 'Nội dung chi tiết thông số kỹ thuật sản phẩm Xi Măng Nghi Sơn PCB40 Mác Cao (Quy cách #2).', NULL, NULL, '/anh-sanpham.png', 'Xi Măng Nghi Sơn PCB40 Mác Cao (Quy cách #2)', 'Báo giá sản phẩm Xi Măng Nghi Sơn PCB40 Mác Cao (Quy cách #2) tại Quảng Trị.', 0, 1, 'published', '2026-09-15 20:01:23', '2026-09-15 20:39:37'),
(1307, 2, 'Xi Măng Sông Gianh Chống Sunfat PCB40 (Quy cách #3)', 'xi-mang-song-gianh-pcb40-item-3', 'SG-PCB40-003', '82000', '90200', 'Bao', 'Mô tả sản phẩm Xi Măng Sông Gianh Chống Sunfat PCB40 (Quy cách #3) phân phối chính hãng tại Siêu thị VLXD Hoàng Yến Quảng Trị.', 'Nội dung chi tiết thông số kỹ thuật sản phẩm Xi Măng Sông Gianh Chống Sunfat PCB40 (Quy cách #3).', NULL, NULL, '/anh-sanpham.png', 'Xi Măng Sông Gianh Chống Sunfat PCB40 (Quy cách #3)', 'Báo giá sản phẩm Xi Măng Sông Gianh Chống Sunfat PCB40 (Quy cách #3) tại Quảng Trị.', 0, 1, 'published', '2026-09-15 20:01:23', '2026-09-15 20:39:37'),
(1308, 10, 'Xi Măng Vicem Hà Tiên Đa Dụng PCB40 (Quy cách #4)', 'xi-mang-ha-tien-pcb40-item-4', 'HT-PCB40-004', '89000', '97900', 'Bao', 'Mô tả sản phẩm Xi Măng Vicem Hà Tiên Đa Dụng PCB40 (Quy cách #4) phân phối chính hãng tại Siêu thị VLXD Hoàng Yến Quảng Trị.', 'Nội dung chi tiết thông số kỹ thuật sản phẩm Xi Măng Vicem Hà Tiên Đa Dụng PCB40 (Quy cách #4).', NULL, NULL, '/anh-sanpham.png', 'Xi Măng Vicem Hà Tiên Đa Dụng PCB40 (Quy cách #4)', 'Báo giá sản phẩm Xi Măng Vicem Hà Tiên Đa Dụng PCB40 (Quy cách #4) tại Quảng Trị.', 0, 1, 'published', '2026-09-15 20:01:23', '2026-09-15 20:39:37'),
(1309, 11, 'Xi Măng Công Thanh PCB40 Quảng Trị (Quy cách #5)', 'xi-mang-cong-thanh-pcb40-item-5', 'CT-PCB40-005', '81000', '89100', 'Bao', 'Mô tả sản phẩm Xi Măng Công Thanh PCB40 Quảng Trị (Quy cách #5) phân phối chính hãng tại Siêu thị VLXD Hoàng Yến Quảng Trị.', 'Nội dung chi tiết thông số kỹ thuật sản phẩm Xi Măng Công Thanh PCB40 Quảng Trị (Quy cách #5).', NULL, NULL, '/anh-sanpham.png', 'Xi Măng Công Thanh PCB40 Quảng Trị (Quy cách #5)', 'Báo giá sản phẩm Xi Măng Công Thanh PCB40 Quảng Trị (Quy cách #5) tại Quảng Trị.', 1, 1, 'published', '2026-09-15 20:01:23', '2026-09-15 20:39:32'),
