(1464, 10, 'Xi Măng Vicem Hà Tiên Đa Dụng PCB40 (Quy cách #160)', 'xi-mang-ha-tien-pcb40-item-160', 'HT-PCB40-160', '89000', '97900', 'Bao', 'Mô tả sản phẩm Xi Măng Vicem Hà Tiên Đa Dụng PCB40 (Quy cách #160) phân phối chính hãng tại Siêu thị VLXD Hoàng Yến Quảng Trị.', 'Nội dung chi tiết thông số kỹ thuật sản phẩm Xi Măng Vicem Hà Tiên Đa Dụng PCB40 (Quy cách #160).', NULL, NULL, '/anh-sanpham.png', 'Xi Măng Vicem Hà Tiên Đa Dụng PCB40 (Quy cách #160)', 'Báo giá sản phẩm Xi Măng Vicem Hà Tiên Đa Dụng PCB40 (Quy cách #160) tại Quảng Trị.', 1, 1, 'published', '2026-09-15 20:01:39', '2026-09-15 20:39:30'),
(1465, 11, 'Xi Măng Công Thanh PCB40 Quảng Trị (Quy cách #161)', 'xi-mang-cong-thanh-pcb40-item-161', 'CT-PCB40-161', '81000', '89100', 'Bao', 'Mô tả sản phẩm Xi Măng Công Thanh PCB40 Quảng Trị (Quy cách #161) phân phối chính hãng tại Siêu thị VLXD Hoàng Yến Quảng Trị.', 'Nội dung chi tiết thông số kỹ thuật sản phẩm Xi Măng Công Thanh PCB40 Quảng Trị (Quy cách #161).', NULL, NULL, '/anh-sanpham.png', 'Xi Măng Công Thanh PCB40 Quảng Trị (Quy cách #161)', 'Báo giá sản phẩm Xi Măng Công Thanh PCB40 Quảng Trị (Quy cách #161) tại Quảng Trị.', 0, 1, 'published', '2026-09-15 20:01:39', '2026-09-15 20:39:32'),
(1466, 3, 'Xi Măng Bỉm Sơn Xây Tô MC25 (Quy cách #162)', 'xi-mang-bim-son-mc25-item-162', 'BS-MC25-162', '76000', '83600', 'Bao', 'Mô tả sản phẩm Xi Măng Bỉm Sơn Xây Tô MC25 (Quy cách #162) phân phối chính hãng tại Siêu thị VLXD Hoàng Yến Quảng Trị.', 'Nội dung chi tiết thông số kỹ thuật sản phẩm Xi Măng Bỉm Sơn Xây Tô MC25 (Quy cách #162).', NULL, NULL, '/anh-sanpham.png', 'Xi Măng Bỉm Sơn Xây Tô MC25 (Quy cách #162)', 'Báo giá sản phẩm Xi Măng Bỉm Sơn Xây Tô MC25 (Quy cách #162) tại Quảng Trị.', 0, 1, 'published', '2026-09-15 20:01:39', '2026-09-15 20:39:32');
