INSERT INTO `posts` (`id`, `author_id`, `title`, `slug`, `summary`, `content`, `featured_image`, `seo_title`, `seo_description`, `category_slug`, `status`, `published_at`, `created_at`) VALUES
(1, 1, 'Giá Thép Xây Dựng Hôm Nay Tại Quảng Trị – Bảng Giá Mới Nhất', 'bang-gia-thep-hoa-phat-quang-tri', 'Cập nhật giá thép xây dựng Hòa Phát tại Quảng Trị, quy cách D6–D25 mác CB300/CB400, bảng trọng lượng barem và báo giá giao tận chân công trình.', '\n<p class="article-lead">Giá thép xây dựng thường thay đổi theo thương hiệu, quy cách, thời điểm và số lượng đặt mua. Bài viết dưới đây tổng hợp bảng giá thép xây dựng Hòa Phát mới nhất và những thông tin kỹ thuật cần biết khi lựa chọn thép cho công trình tại Quảng Trị.</p>\n\n<h2 id="1-bang-gia-thep-xay-dung-hoa-phat-hom-nay-tai-quang-tri">1. Bảng giá thép xây dựng Hòa Phát hôm nay tại Quảng Trị</h2>\n<p>Siêu thị VLXD Hoàng Yến là đại lý phân phối cấp 1 thép xây dựng Hòa Phát tại tỉnh Quảng Trị. Dưới đây là bảng giá thép thanh vằn và thép cuộn xuất kho mới nhất:</p>\n\n<div class="table-responsive">\n  <table class="table-industrial">\n    <thead>\n      <tr>\n        <th>STT</th>\n        <th>Quy Cách / Chủng Loại</th>\n        <th>Mác Thép</th>\n        <th>Trọng Lượng (kg/cây 11.7m)</th>\n        <th>Đơn Vị</th>\n        <th>Đơn Giá Tham Khảo (VNĐ)</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td>1</td>\n        <td>Thép cuộn trơn D6 (Phi 6)</td>\n        <td>CT3 / SAE1008</td>\n        <td>0.222 kg/m</td>\n        <td>Kg</td>\n        <td><strong>15.200 - 15.800</strong></td>\n      </tr>\n      <tr>\n        <td>2</td>\n        <td>Thép cuộn trơn D8 (Phi 8)</td>\n        <td>CT3 / SAE1008</td>\n        <td>0.395 kg/m</td>\n        <td>Kg</td>\n        <td><strong>15.200 - 15.800</strong></td>\n      </tr>\n      <tr>\n        <td>3</td>\n        <td>Thép cây vằn D10 (Phi 10)</td>\n        <td>CB300V</td>\n        <td>7.22 kg/cây</td>\n        <td>Cây</td>\n        <td><strong>110.000 - 118.000</strong></td>\n      </tr>\n      <tr>\n        <td>4</td>\n        <td>Thép cây vằn D12 (Phi 12)</td>\n        <td>CB300V</td>\n        <td>10.39 kg/cây</td>\n        <td>Cây</td>\n        <td><strong>158.000 - 169.000</strong></td>\n      </tr>\n      <tr>\n        <td>5</td>\n        <td>Thép cây vằn D14 (Phi 14)</td>\n        <td>CB300V / CB400V</td>\n        <td>14.16 kg/cây</td>\n        <td>Cây</td>\n        <td><strong>215.000 - 230.000</strong></td>\n      </tr>\n      <tr>\n        <td>6</td>\n        <td>Thép cây vằn D16 (Phi 16)</td>\n        <td>CB300V / CB400V</td>\n        <td>18.49 kg/cây</td>\n        <td>Cây</td>\n        <td><strong>280.000 - 298.000</strong></td>\n      </tr>\n      <tr>\n        <td>7</td>\n        <td>Thép cây vằn D18 (Phi 18)</td>\n        <td>CB300V / CB400V</td>\n        <td>23.40 kg/cây</td>\n        <td>Cây</td>\n        <td><strong>355.000 - 378.000</strong></td>\n      </tr>\n      <tr>\n        <td>8</td>\n        <td>Thép cây vằn D20 (Phi 20)</td>\n        <td>CB300V / CB400V</td>\n        <td>28.88 kg/cây</td>\n        <td>Cây</td>\n        <td><strong>438.000 - 465.000</strong></td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n\n<div class="article-note-box">\n  <div class="note-icon">💡</div>\n  <div class="note-content">\n    <strong>Lưu ý về đơn giá:</strong> Giá thép biến động theo thị trường quặng sắt thế giới và chính sách giá nhà máy từng ngày. Đơn giá trên áp dụng giao hàng tại khu vực Đông Hà, Triệu Phong, Gio Linh, Cam Lộ, Vĩnh Linh, Quảng Trị. Với số lượng lớn cho công trình dự án, vui lòng gọi Hotline <strong>0946.575.579</strong> để nhận chiết khấu trực tiếp.\n  </div>\n</div>\n\n<h2 id="2-cac-loai-thep-xay-dung-hoa-phat-pho-bien-va-ung-dung">2. Các loại thép xây dựng Hòa Phát phổ biến và ứng dụng</h2>\n\n<h3 id="2-1-thep-cuon-phi-6-va-phi-8">2.1. Thép cuộn Phi 6 và Phi 8 (D6, D8)</h3>\n<p>Thép cuộn tròn trơn Hòa Phát bề mặt nhẵn bóng, cơ tính dẻo dai, dễ uốn nắn. Thường dùng gia công móc đai cho cột, đai dầm, làm kết cấu lưới thép sàn phụ gia và đan sắt nền móng.</p>\n\n<figure class="article-img-figure">\n  <img src="https://vlxdhoangyen.com/wp-content/uploads/2025/07/thep-cuon-phi-8.jpg" alt="Thép cuộn phi 8 Hòa Phát tại kho Hoàng Yến" />\n  <figcaption>Thép cuộn tròn trơn phi 8 Hòa Phát dẻo dai, dễ uốn bẻ đai cột dầm công trình</figcaption>\n</figure>\n\n<h3 id="2-2-thep-thanh-van-d10-den-d25">2.2. Thép thanh vằn D10 đến D25 (Thép cây)</h3>\n<p>Thép thanh vằn có gân gờ nổi giúp tăng độ bám dính chắc chắn với khối bê tông. Đây là vật liệu cốt lõi chịu lực uốn và kéo cho toàn bộ khung sườn ngôi nhà từ đài móng, cổ cột, dầm sàn tầng đến mái.</p>\n\n<h2 id="3-phan-biet-mac-thep-cb300v-va-cb400v">3. Phân biệt mác thép CB300V và CB400V</h2>\n<p>Ký hiệu mác thép thể hiện giới hạn chảy và khả năng chịu lực nén kéo của thanh thép:</p>\n<ul>\n  <li><strong>Mác CB300V:</strong> Thường dùng cho nhà phố, biệt thự gia đình từ 1 đến 4 tầng. Thép có độ dẻo vừa phải, dễ uốn gập mỏ tại công trường.</li>\n  <li><strong>Mác CB400V / CB500V:</strong> Thép cường độ cao chuyên dùng cho nhà cao tầng, công trình công nghiệp, mố cầu và dự án có khẩu độ dầm lớn.</li>\n</ul>\n\n<h2 id="4-kinh-nghiem-nhan-biet-thep-hoa-phat-chinh-hang">4. Kinh nghiệm nhận biết thép Hòa Phát chính hãng</h2>\n<p>Để tránh mua phải thép giả, thép gầy âm barem làm ảnh hưởng an toàn kết cấu công trình, quý khách cần lưu ý các dấu hiệu:</p>\n<ul>\n  <li><strong>Logo dập nổi:</strong> Có biểu tượng 3 hình tam giác và chữ <strong>HOA PHAT</strong> dập nổi sắc nét trên từng mét thân thép.</li>\n  <li><strong>Ký hiệu mác thép và đường kính:</strong> Ví dụ: <em>HOA PHAT - CB300 - D14</em> rõ ràng, không bị mờ nhòe.</li>\n  <li><strong>Bề mặt thép:</strong> Màu xanh ánh kim đặc trưng, trơn láng, không sần sùi hay có vảy rỉ đỏ.</li>\n  <li><strong>Tem mác đầu bó:</strong> Bó thép nguyên đai nguyên kiện luôn có mã QR code, ngày giờ sản xuất, lô cán và dấu kiểm định KCS nhà máy.</li>\n</ul>\n\n<h2 id="5-cau-hoi-thuong-gap-ve-thep-xay-dung">5. Câu hỏi thường gặp về thép xây dựng</h2>\n<div class="faq-container">\n  <div class="faq-item">\n    <h3 class="faq-question">1 cây thép xây dựng dài bao nhiêu mét?</h3>\n    <div class="faq-answer">\n      <p>Tất cả thép cây thanh vằn Hòa Phát xuất xưởng tiêu chuẩn đều có chiều dài cố định là <strong>11.7 mét</strong>. Đối với các công trình đặc thù, nhà máy có thể cắt quy cách theo đơn đặt hàng trước.</p>\n    </div>\n  </div>\n  <div class="faq-item">\n    <h3 class="faq-question">1 tấn thép D10, D12, D14 gồm bao nhiêu cây?</h3>\n    <div class="faq-answer">\n      <p>Dựa trên barem tiêu chuẩn: 1 tấn thép D10 khoảng 138 cây; 1 tấn thép D12 khoảng 96 cây; 1 tấn thép D14 khoảng 70 cây; 1 tấn thép D16 khoảng 54 cây.</p>\n    </div>\n  </div>\n  <div class="faq-item">\n    <h3 class="faq-question">Hoàng Yến có hỗ trợ giao thép tận chân công trình tại Quảng Trị không?</h3>\n    <div class="faq-answer">\n      <p>Có. VLXD Hoàng Yến sở hữu đội xe tải thùng và xe cẩu chuyên dụng giao sắt thép tận chân công trình tại tất cả các huyện thị TP. Đông Hà, Triệu Phong, Cam Lộ, Gio Linh, Vĩnh Linh, Hải Lăng, Hướng Hóa.</p>\n    </div>\n  </div>\n</div>\n\n<div class="article-conclusion-box">\n  <h3>Kết luận & Tư vấn</h3>\n  <p>Trên đây là những thông tin cần biết về bảng giá thép xây dựng Hòa Phát và cách lựa chọn quy cách phù hợp cho công trình. Giá vật tư xây dựng có thể biến động theo từng đợt điều chỉnh của nhà máy. Khách hàng và nhà thầu tại Quảng Trị cần bảng dự toán sắt thép chính xác theo khối lượng bản vẽ có thể liên hệ ngay VLXD Hoàng Yến để được hỗ trợ bóc tách và nhận báo giá xuất xưởng tốt nhất.</p>\n</div>\n    ', '/images/banner-vlxdhoangyen.png', 'Giá Thép Xây Dựng Hôm Nay Tại Quảng Trị | VLXD Hoàng Yến', 'Cập nhật giá thép xây dựng Hòa Phát tại Quảng Trị, quy cách D6–D25 mác CB300/CB400, bảng trọng lượng barem và báo giá giao tận chân công trình.', 'tin-tuc', 'published', '2026-09-15 18:16:18', '2026-09-15 18:16:18'),
(2, 1, 'Gạch Tuynel Là Gì? Phân Loại, Kích Thước Và Giá Gạch Tuynel Tại Quảng Trị', 'gach-tuynel-la-gi-phan-loai-kich-thuoc-bao-gia', 'Gạch tuynel là gì? Tìm hiểu chi tiết các loại gạch tuynel 2 lỗ, 4 lỗ, 6 lỗ, gạch đặc, bảng kích thước tiêu chuẩn, định mức xây và báo giá mới nhất tại Quảng Trị.', '\n<p class="article-lead">Gạch tuynel là vật liệu xây thô quen thuộc và không thể thiếu trong kết cấu tường bao, tường ngăn của mọi ngôi nhà. Bài viết dưới đây tổng hợp chi tiết cấu tạo, phân loại, kích thước và bảng giá gạch tuynel mới nhất tại thị trường Quảng Trị.</p>\n\n<h2 id="1-gach-tuynel-la-gi">1. Gạch tuynel là gì?</h2>\n<p>Gạch Tuynel là loại gạch đất sét nung được sản xuất bằng công nghệ lò nung tuynel liên tục hiện đại. Đất sét sau khi được ngâm ủ kỹ lưỡng sẽ được đùn ép chân không, cắt theo kích thước chuẩn, sấy khô và nung ở nhiệt độ cao từ 900°C – 1050°C. Nhờ đó viên gạch có màu đỏ tươi tự nhiên, đanh chắc, chịu lực nén cao và khả năng chống thấm nước tốt hơn nhiều so với gạch thủ công truyền thống.</p>\n\n<figure class="article-img-figure">\n  <img src="https://vlxdhoangyen.com/wp-content/uploads/2025/07/gachtuynel-1.jpg" alt="Gạch tuynel đất sét nung chất lượng cao tại kho VLXD Hoàng Yến" />\n  <figcaption>Gạch tuynel đất nung công nghệ lò tuynel hiện đại màu đỏ tươi, đanh chắc chịu lực cao</figcaption>\n</figure>\n\n<h2 id="2-cac-loai-gach-tuynel-pho-bien">2. Các loại gạch tuynel phổ biến hiện nay</h2>\n\n<h3 id="2-1-gach-tuynel-6-lo">2.1. Gạch tuynel 6 lỗ</h3>\n<p>Gạch tuynel 6 lỗ là dòng gạch được sử dụng rộng rãi nhất tại miền Trung và Quảng Trị. Với thiết kế 6 lỗ rỗng chạy dọc thân viên gạch, loại gạch này giúp giảm tải trọng cho móng nhà, tăng khả năng cách âm, cách nhiệt và tiết kiệm đáng kể vữa xây.</p>\n\n<h3 id="2-2-gach-tuynel-2-lo-va-4-lo">2.2. Gạch tuynel 2 lỗ và 4 lỗ</h3>\n<p>Gạch 2 lỗ (gạch thông tâm) và 4 lỗ thường dùng để xây các bức tường ngăn chia phòng ngủ, phòng khách hoặc các vị trí tường không phải chịu tải trọng quá nặng.</p>\n\n<h3 id="2-3-gach-dac-tuynel">2.3. Gạch đặc tuynel (Gạch thẻ đặc)</h3>\n<p>Gạch đặc không có lỗ rỗng, kết cấu đặc chắc hoàn toàn. Đây là dòng gạch chịu lực nén cao nhất và chống thấm nước vượt trội, chuyên dụng cho xây móng nhà, bể nước ngầm, hố ga, tường nhà vệ sinh và các hàng gạch giằng chân tường.</p>\n\n<h2 id="3-kich-thuoc-va-thong-so-ky-thuat-gach-tuynel">3. Kích thước và thông số kỹ thuật gạch tuynel</h2>\n\n<div class="table-responsive">\n  <table class="table-industrial">\n    <thead>\n      <tr>\n        <th>Loại Gạch</th>\n        <th>Kích Thước Tiêu Chuẩn (Dài x Rộng x Cao mm)</th>\n        <th>Trọng Lượng (kg/viên)</th>\n        <th>Cường Độ Nén (Mác)</th>\n        <th>Độ Hút Nước (%)</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td>Gạch tuynel 6 lỗ</td>\n        <td>195 x 135 x 90</td>\n        <td>~ 2.4 - 2.6 kg</td>\n        <td>Mác 75</td>\n        <td>&lt; 12%</td>\n      </tr>\n      <tr>\n        <td>Gạch tuynel 4 lỗ</td>\n        <td>190 x 80 x 80</td>\n        <td>~ 1.2 - 1.4 kg</td>\n        <td>Mác 75</td>\n        <td>&lt; 12%</td>\n      </tr>\n      <tr>\n        <td>Gạch tuynel 2 lỗ</td>\n        <td>200 x 95 x 55</td>\n        <td>~ 1.3 - 1.5 kg</td>\n        <td>Mác 50 - 75</td>\n        <td>&lt; 14%</td>\n      </tr>\n      <tr>\n        <td>Gạch đặc tuynel</td>\n        <td>205 x 95 x 55</td>\n        <td>~ 2.1 - 2.3 kg</td>\n        <td>Mác 100 - 150</td>\n        <td>&lt; 10%</td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n\n<h2 id="4-cach-tinh-so-luong-gach-can-xay-cho-1m2-tuong">4. Cách tính số lượng gạch cần xây cho 1m² tường</h2>\n<p>Để dự toán số lượng vật tư chính xác khi xây nhà tại Quảng Trị, bạn có thể áp dụng định mức chuẩn sau:</p>\n<ul>\n  <li><strong>Tường 10 (Tường đơn dày 10cm):</strong> Sử dụng khoảng <strong>45 – 50 viên</strong> gạch 6 lỗ hoặc <strong>65 – 70 viên</strong> gạch 2 lỗ cho 1m² tường (đã tính mạch vữa 1cm).</li>\n  <li><strong>Tường 20 (Tường đôi dày 20cm):</strong> Sử dụng khoảng <strong>90 – 100 viên</strong> gạch 6 lỗ hoặc <strong>130 – 140 viên</strong> gạch 2 lỗ cho 1m² tường.</li>\n</ul>\n\n<h2 id="5-gia-gach-tuynel-hien-nay-tai-quang-tri">5. Giá gạch tuynel hiện nay tại Quảng Trị</h2>\n<p>Giá gạch tuynel phụ thuộc vào nhà máy sản xuất, cự ly vận chuyển và quy cách đóng bó/pallet:</p>\n<ul>\n  <li><strong>Gạch tuynel 6 lỗ:</strong> Dao động từ <strong>2.200đ – 2.800đ / viên</strong> (giao tận công trình).</li>\n  <li><strong>Gạch tuynel 2 lỗ:</strong> Dao động từ <strong>1.100đ – 1.400đ / viên</strong>.</li>\n  <li><strong>Gạch đặc tuynel mác cao:</strong> Dao động từ <strong>1.500đ – 1.900đ / viên</strong>.</li>\n</ul>\n\n<h2 id="6-kinh-nghiem-chon-mua-gach-tuynel-chuan-chat-luong">6. Kinh nghiệm chọn mua gạch tuynel chuẩn chất lượng</h2>\n<ul>\n  <li><strong>Màu sắc:</strong> Chọn gạch có màu đỏ cam tươi hoặc đỏ sẫm đồng đều. Tránh mua gạch màu quá nhạt (gạch non lửa, dễ vỡ) hoặc màu đen xỉn (gạch già lửa quá mức bị cong vênh).</li>\n  <li><strong>Âm thanh gõ:</strong> Dùng thanh kim loại gõ nhẹ vào viên gạch, gạch tuynel đạt chuẩn sẽ phát ra tiếng keng đanh chắc.</li>\n  <li><strong>Thử độ hút nước:</strong> Nhỏ vài giọt nước lên bề mặt viên gạch. Gạch tốt hút nước vừa phải, không ngấm quá nhanh.</li>\n</ul>\n\n<h2 id="7-cau-hoi-thuong-gap-ve-gach-tuynel">7. Câu hỏi thường gặp về gạch tuynel</h2>\n<div class="faq-container">\n  <div class="faq-item">\n    <h3 class="faq-question">Nên xây tường bao bằng gạch 6 lỗ hay gạch 2 lỗ?</h3>\n    <div class="faq-answer">\n      <p>Tại Quảng Trị với khí hậu mùa hè nắng nóng gay gắt và mùa đông gió lạnh, hầu hết các công trình ưu tiên xây tường bao bằng <strong>gạch 6 lỗ</strong> nhờ lớp đệm không khí dày giúp cách nhiệt chống nóng rất tốt.</p>\n    </div>\n  </div>\n  <div class="faq-item">\n    <h3 class="faq-question">1 xe tải chở được bao nhiêu viên gạch tuynel?</h3>\n    <div class="faq-answer">\n      <p>Tùy theo tải trọng xe: Xe tải 3.5 tấn chở khoảng 1.500 - 1.800 viên gạch 6 lỗ; xe tải 8 tấn chở khoảng 3.500 - 4.000 viên; xe ben/xe cẩu chuyên dụng chở từ 6.000 - 8.000 viên mỗi chuyến.</p>\n    </div>\n  </div>\n</div>\n\n<div class="article-conclusion-box">\n  <h3>Kết luận & Mua hàng</h3>\n  <p>Trên đây là toàn bộ thông tin về đặc điểm, phân loại và bảng giá gạch tuynel đất sét nung tại Quảng Trị. Khách hàng, chủ nhà và đội thầu cần đặt mua gạch số lượng lớn kèm cam kết tỷ lệ vỡ vụn dưới 2% và giao hàng đúng tiến độ hãy liên hệ ngay Siêu thị VLXD Hoàng Yến.</p>\n</div>\n    ', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/gachtuynel-1.jpg', 'Gạch Tuynel Là Gì? Phân Loại, Kích Thước & Báo Giá Tại Quảng Trị', 'Tìm hiểu gạch tuynel 2 lỗ, 4 lỗ, 6 lỗ, gạch đặc, thông số kỹ thuật kích thước và bảng giá gạch xây dựng mới nhất tại Đông Hà Quảng Trị.', 'tin-tuc', 'published', '2026-09-15 18:16:18', '2026-09-15 18:16:18'),
(3, 1, 'Báo Giá Xi Măng Bỉm Sơn, Nghi Sơn, Sông Gianh PCB30 & PCB40 Tại Quảng Trị', 'bao-gia-xi-mang-quang-tri', 'Cập nhật bảng giá xi măng Bỉm Sơn Con Voi, Nghi Sơn, Sông Gianh PCB30, PCB40 mới nhất hôm nay tại Quảng Trị. Cách phân biệt xi măng xây tô và đổ bê tông.', '\n<p class="article-lead">Xi măng là chất kết dính quan trọng nhất trong thi công công trình từ khâu đào móng, đổ dầm cột sàn cho đến xây tường hoàn thiện. Bài viết dưới đây cập nhật bảng báo giá các thương hiệu xi măng uy tín hàng đầu và kinh nghiệm lựa chọn mác xi măng chuẩn kỹ thuật tại Quảng Trị.</p>\n\n<h2 id="1-bang-gia-xi-mang-xay-dung-moi-nhat-tai-quang-tri">1. Bảng giá xi măng xây dựng mới nhất tại Quảng Trị</h2>\n<p>VLXD Hoàng Yến là tổng đại lý phân phối cấp 1 các thương hiệu xi măng lớn tại miền Trung. Dưới đây là giá tham khảo (đóng bao 50kg):</p>\n\n<div class="table-responsive">\n  <table class="table-industrial">\n    <thead>\n      <tr>\n        <th>STT</th>\n        <th>Tên Sản Phẩm Xi Măng</th>\n        <th>Mác Xi Măng</th>\n        <th>Quy Cách Đóng Bao</th>\n        <th>Ứng Dụng Chính</th>\n        <th>Đơn Giá Tham Khảo (VNĐ/Bao)</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td>1</td>\n        <td>Xi Măng Bỉm Sơn Con Voi PCB40</td>\n        <td>PCB40</td>\n        <td>50 kg</td>\n        <td>Đổ móng, dầm, cột, sàn chịu lực cao</td>\n        <td><strong>88.000 - 94.000</strong></td>\n      </tr>\n      <tr>\n        <td>2</td>\n        <td>Xi Măng Nghi Sơn PCB40 Đa Dụng</td>\n        <td>PCB40</td>\n        <td>50 kg</td>\n        <td>Bê tông cường độ sớm, kết cấu dân dụng</td>\n        <td><strong>89.000 - 95.000</strong></td>\n      </tr>\n      <tr>\n        <td>3</td>\n        <td>Xi Măng Sông Gianh PCB40 Kháng Mặn</td>\n        <td>PCB40</td>\n        <td>50 kg</td>\n        <td>Bền sunfat, chống ăn mòn ven biển</td>\n        <td><strong>85.000 - 90.000</strong></td>\n      </tr>\n      <tr>\n        <td>4</td>\n        <td>Xi Măng Bỉm Sơn Xây Trát PCB30</td>\n        <td>PCB30</td>\n        <td>50 kg</td>\n        <td>Xây tường gạch, trát tường trong ngoài</td>\n        <td><strong>76.000 - 82.000</strong></td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n\n<h2 id="2-phan-biet-xi-mang-pcb30-va-pcb40">2. Phân biệt xi măng PCB30 và PCB40</h2>\n\n<h3 id="2-1-xi-mang-pcb30-chuyen-dung-xay-trat">2.1. Xi măng PCB30 (Chuyên dụng xây trát)</h3>\n<p>Xi măng PCB30 có cường độ nén sau 28 ngày đạt tối thiểu 30 N/mm². Dòng sản phẩm này có độ mịn cực cao, độ dẻo vữa vượt trội giúp thợ hồ dễ miết bay, tăng độ bám dính và giữ nước tốt, hạn chế tối đa nứt chân chim trên bề mặt tường tô.</p>\n\n<h3 id="2-2-xi-mang-pcb40-chuyen-dung-be-tong-ket-cau">2.2. Xi măng PCB40 (Chuyên dụng bê tông kết cấu)</h3>\n<p>Xi măng PCB40 có cường độ nén sau 28 ngày đạt tối thiểu 40 N/mm². Đây là lựa chọn bắt buộc cho các hạng mục kết cấu chịu lực như móng băng, móng cọc, dầm ngang, sàn bê tông cốt thép, bể chứa nước ngầm.</p>\n\n<figure class="article-img-figure">\n  <img src="https://vlxdhoangyen.com/wp-content/uploads/2025/07/bimsonpcb40.png" alt="Xi măng Bỉm Sơn PCB40 chính hãng tại kho Hoàng Yến" />\n  <figcaption>Xi măng Bỉm Sơn Con Voi PCB40 cường độ cao chuyên dụng đổ móng dầm sàn</figcaption>\n</figure>\n\n<h2 id="3-ty-le-cap-phoi-vua-va-be-tong-chuan-ky-thuat">3. Tỷ lệ cấp phối vữa và bê tông chuẩn kỹ thuật</h2>\n<p>Để đảm bảo độ bền công trình 50 - 100 năm, thợ thi công nên tuân thủ tỷ lệ trộn theo tiêu chuẩn khuyến cáo của nhà máy:</p>\n<ul>\n  <li><strong>Bê tông mác 200 (1 bao xi măng 50kg PCB40):</strong> Trộn cùng khoảng 4 thùng cát vàng (thùng 18L) + 6-7 thùng đá 1x2 + nước vừa đủ.</li>\n  <li><strong>Bê tông mác 250 (1 bao xi măng 50kg PCB40):</strong> Trộn cùng khoảng 3.5 thùng cát vàng + 5-6 thùng đá 1x2 + nước vừa đủ.</li>\n  <li><strong>Vữa xây tô mác 75 (1 bao xi măng 50kg PCB30):</strong> Trộn cùng khoảng 8 thùng cát mịn sạch.</li>\n</ul>\n\n<h2 id="4-cau-hoi-thuong-gap-khi-mua-xi-mang">4. Câu hỏi thường gặp khi mua xi măng</h2>\n<div class="faq-container">\n  <div class="faq-item">\n    <h3 class="faq-question">Xi măng để được bao lâu trong kho?</h3>\n    <div class="faq-answer">\n      <p>Xi măng bảo quản nơi khô ráo, kê trên pallet cách đất 20cm có hạn sử dụng tốt nhất trong vòng <strong>60 ngày (2 tháng)</strong> kể từ ngày sản xuất in trên vỏ bao. Hoàng Yến luôn cam kết xuất hàng date mới xuất xưởng dưới 15 ngày.</p>\n    </div>\n  </div>\n  <div class="faq-item">\n    <h3 class="faq-question">1 tấn xi măng gồm bao nhiêu bao?</h3>\n    <div class="faq-answer">\n      <p>1 bao xi măng tiêu chuẩn tại Việt Nam đóng 50kg. Như vậy 1 tấn xi măng tương đương với đúng <strong>20 bao</strong>.</p>\n    </div>\n  </div>\n</div>\n\n<div class="article-conclusion-box">\n  <h3>Kết luận & Đặt hàng</h3>\n  <p>Hy vọng qua bài viết trên, quý khách hàng và nhà thầu đã nắm rõ bảng giá cũng như cách chọn loại xi măng phù hợp cho từng giai đoạn xây nhà. Siêu thị VLXD Hoàng Yến cam kết 100% xi măng chính hãng, hóa đơn chứng từ đầy đủ và xe tải giao hàng tận chân công trình.</p>\n</div>\n    ', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/bimsonpcb40.png', 'Báo Giá Xi Măng Bỉm Sơn, Nghi Sơn Tại Quảng Trị | VLXD Hoàng Yến', 'Bảng giá xi măng Bỉm Sơn PCB40, Nghi Sơn, Sông Gianh, xi măng xây trát PCB30 tại Đông Hà Quảng Trị. Giao hàng tận nơi.', 'tin-tuc', 'published', '2026-09-15 18:16:18', '2026-09-15 18:16:18'),
(4, 1, 'Mua Vật Liệu Xây Dựng Ở Đâu Tại Đông Hà, Quảng Trị Uy Tín?', 'mua-vat-lieu-xay-dung-o-dau-tai-dong-ha-quang-tri', 'Tìm địa chỉ mua vật liệu xây dựng uy tín tại Đông Hà, Quảng Trị? Siêu Thị VLXD Hoàng Yến cung cấp xi măng, sắt thép, gạch ốp lát chính hãng, giá cạnh tranh.', '<p>Nhu cầu xây dựng hạ tầng, nhà ở dân dụng và công trình thương mại tại khu vực TP. Đông Hà cũng như toàn tỉnh Quảng Trị đang gia tăng nhanh chóng. Một trong những quyết định quan trọng nhất của chủ đầu tư và nhà thầu là tìm kiếm đơn vị cung ứng vật tư đáng tin cậy. Vậy <strong>mua vật liệu xây dựng ở đâu tại Đông Hà, Quảng Trị</strong> để vừa đảm bảo tiêu chuẩn kỹ thuật, vừa tối ưu chi phí vận chuyển và tiến độ thi công?</p><h2>Tiêu chí lựa chọn đại lý vật liệu xây dựng uy tín tại Quảng Trị</h2><p>Vật liệu xây dựng quyết định trực tiếp đến độ bền vững, tính an toàn và thẩm mỹ của toàn bộ công trình. Khi chọn địa chỉ cung cấp vật tư, các chủ đầu tư nên dựa trên các tiêu chí sau:</p><ul><li><strong>Nguồn gốc xuất xứ rõ ràng:</strong> Sản phẩm sắt thép, xi măng, gạch ốp lát, sơn... cần có chứng nhận hợp chuẩn hợp quy từ nhà sản xuất.</li><li><strong>Chủng loại hàng hóa phong phú:</strong> Cung cấp đầy đủ từ vật liệu xây dựng thô (xi măng, cát, đá, thép) đến vật liệu hoàn thiện (gạch trang trí, thiết bị vệ sinh, sơn chống thấm).</li><li><strong>Năng lực vận chuyển linh hoạt:</strong> Đội ngũ xe tải giao hàng tận chân công trình đúng hẹn, đảm bảo không làm gián đoạn tiến độ thi công.</li><li><strong>Tư vấn kỹ thuật chuyên sâu:</strong> Hỗ trợ khách hàng tính toán khối lượng vật tư chính xác, tránh lãng phí hoặc thiếu hụt nguyên vật liệu.</li></ul><h2>Siêu Thị VLXD Hoàng Yến – Điểm đến tin cậy cho mọi công trình tại Đông Hà</h2><p>Tọa lạc tại địa chỉ <strong>299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị</strong>, <strong>Siêu Thị VLXD Hoàng Yến</strong> là trung tâm phân phối vật liệu xây dựng và hoàn thiện quy mô lớn, đáp ứng trọn gói nhu cầu của các dự án lớn nhỏ trên địa bàn.</p><h3>1. Vật liệu xây dựng phần thô tiêu chuẩn</h3><p>Hoàng Yến phân phối các dòng sản phẩm phần thô đạt tiêu chuẩn chất lượng cao, phục vụ thi công móng, cột, dầm, sàn:</p><ul><li><strong>Thép xây dựng:</strong> Thép cuộn, thép thanh vằn từ các thương hiệu hàng đầu (Hòa Phát, Việt Nhật, POMINA...) đạt tiêu chuẩn TCVN, JIS, ASTM.</li><li><strong>Xi măng:</strong> Các dòng xi măng PCB30, PCB40 chuyên dụng cho đổ bê tông và xây trát.</li><li><strong>Gạch xây, cát, đá:</strong> Gạch tuynel, gạch không nung, cát vàng đổ bê tông, đá 1x2, đá 4x6 đạt quy chuẩn cơ lý.</li></ul><h3>2. Vật liệu hoàn thiện và trang trí nội ngoại thất</h3><p>Bên cạnh vật tư thô, Siêu Thị VLXD Hoàng Yến sở hữu không gian trưng bày đa dạng các dòng sản phẩm hoàn thiện cao cấp:</p><ul><li><strong>Gạch ốp lát:</strong> Gạch ceramic, porcelain, granite đa dạng kích thước (60x60cm, 80x80cm, 60x120cm) phù hợp lót nền, ốp tường.</li><li><strong>Thiết bị vệ sinh &amp; phòng tắm:</strong> Bồn cầu, lavabo, vòi sen tắm chịu lực, kháng khuẩn.</li><li><strong>Sơn &amp; Chống thấm:</strong> Hóa chất chống thấm sika, sơn lót, sơn phủ nội ngoại thất bền màu dưới thời tiết khắc nghiệt tại Quảng Trị.</li></ul><h2><span style="font-size: 0.95rem;">Hướng dẫn bảo quản vật tư xây dựng tại công trình</span></h2><p>Để giữ nguyên chất lượng vật tư trong suốt quá trình thi công, đơn vị thi công cần lưu ý các quy tắc bảo quản sau:</p><ul><li><strong>Đối với xi măng:</strong> Xếp trên pallet gỗ cách mặt đất tối thiểu 20cm, cách tường 30cm, bảo quản nơi khô ráo, kín gió.</li><li><strong>Đối với sắt thép:</strong> Phân loại theo đường kính, kê cao cách mặt đất và dùng bạt che phủ chống oxy hóa, rỉ sét do mưa nắng.</li><li><strong>Đối với gạch ốp lát:</strong> Xếp đứng các thùng gạch, tránh đè nén quá tải trọng cho phép và giữ nguyên bao bì bảo vệ góc cạnh.</li></ul>blockquote&gt;<strong>Lưu ý công trình:</strong> Do đặc thù thời tiết mưa bão khắc nghiệt tại Quảng Trị, chủ đầu tư nên tập kết vật tư hoàn thiện ở khu vực có mái che chắn an toàn. Để nhận báo giá chính xác và ưu đãi mới nhất theo khối lượng công trình, quý khách vui lòng liên hệ trực tiếp Hotline: <strong>0946.575.579</strong>.<h2>Các câu hỏi thường gặp (FAQ)</h2><h3>1. Mua vật liệu xây dựng ở đâu tại Đông Hà, Quảng Trị giao hàng tận nơi?</h3><p>Siêu Thị VLXD Hoàng Yến tại 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị hỗ trợ giao hàng tận chân công trình trên toàn địa bàn TP. Đông Hà và các huyện lân cận thuộc tỉnh Quảng Trị.</p><h3>2. Làm thế nào để nhận báo giá vật liệu xây dựng mới nhất?</h3><p>Quý khách có thể gửi bảng khối lượng vật tư qua Hotline/Zalo <strong>0946.575.579</strong> hoặc đến trực tiếp showroom tại 299 Lê Duẩn để đội ngũ nhân viên hỗ trợ bóc tách khối lượng và lập bảng báo giá chi tiết.</p><h3>3. Siêu Thị VLXD Hoàng Yến có cung cấp hóa đơn VAT và giấy chứng nhận chất lượng (CO/CQ) không?</h3><p>Có. Tất cả các mặt hàng sắt thép, xi măng, gạch ốp lát chính hãng phân phối tại Hoàng Yến đều có đầy đủ chứng nhận chất lượng từ nhà sản xuất và hỗ trợ xuất hóa đơn VAT theo yêu cầu của dự án.</p><h3>4. Cần chuẩn bị những gì trước khi đặt mua vật tư phần thô?</h3><p>Chủ đầu tư nên tham khảo ý kiến của kiến trúc sư hoặc kỹ sư giám sát để chốt khối lượng dự toán, xác định mặt bằng tập kết vật tư và thống nhất tiến độ giao hàng theo từng giai đoạn thi công.</p>', '/images/uploads/1789559824494-mua-v-t-li-u-u-t-i-ng-h-qu-ng-tr-.png', 'Mua Vật Liệu Xây Dựng Ở Đâu Tại Đông Hà, Quảng Trị? - Hoàng Yến', 'Gợi ý địa chỉ mua vật liệu xây dựng uy tín tại Đông Hà, Quảng Trị. Siêu Thị VLXD Hoàng Yến - 299 Lê Duẩn chuyên vật tư thô & hoàn thiện chất lượng cao.', 'tin-tuc', 'published', '2026-09-16 11:55:15', '2026-09-16 11:55:15'),
(26, NULL, 'Bảng Trọng Lượng Thép Xây Dựng D6 Đến D32 Chuẩn TCVN 1651 Mới Nhất', 'bang-trong-luong-thep-xay-dung-d6-d32', 'Bảng tra cứu trọng lượng thép xây dựng từ phi D6 đến D32 chuẩn TCVN 1651:2018. Chi tiết khối lượng 1 mét, 1 cây 11,7m và số cây trên 1 tấn thép kèm công thức tính chuẩn xác.', '\n<p>Bảng trọng lượng thép xây dựng là tài liệu kỹ thuật cốt lõi giúp các kỹ sư kết cấu, nhà thầu thi công và chủ nhà bóc tách khối lượng dự toán, kiểm tra tải trọng thiết kế và nghiệm thu sắt thép thực tế tại chân công trình.</p>\n\n<div class="callout-box">\n  <strong>Tóm tắt trọng lượng danh nghĩa các loại thép phổ biến nhất (theo TCVN 1651-2:2018):</strong><br>\n  - <strong>Thép D6:</strong> 0,222 kg/m (Dạng cuộn)<br>\n  - <strong>Thép D8:</strong> 0,395 kg/m (Dạng cuộn hoặc cây)<br>\n  - <strong>Thép D10:</strong> 0,617 kg/m &rarr; <strong>7,22 kg/cây 11,7m</strong> (138 cây/tấn)<br>\n  - <strong>Thép D12:</strong> 0,888 kg/m &rarr; <strong>10,39 kg/cây 11,7m</strong> (96 cây/tấn)<br>\n  - <strong>Thép D14:</strong> 1,210 kg/m &rarr; <strong>14,16 kg/cây 11,7m</strong> (70 cây/tấn)<br>\n  - <strong>Thép D16:</strong> 1,580 kg/m &rarr; <strong>18,49 kg/cây 11,7m</strong> (54 cây/tấn)<br>\n  - <strong>Thép D18:</strong> 2,000 kg/m &rarr; <strong>23,40 kg/cây 11,7m</strong> (42 cây/tấn)<br>\n  - <strong>Thép D20:</strong> 2,470 kg/m &rarr; <strong>28,90 kg/cây 11,7m</strong> (34 cây/tấn)<br>\n  - <strong>Thép D22:</strong> 2,980 kg/m &rarr; <strong>34,87 kg/cây 11,7m</strong> (28 cây/tấn)<br>\n  - <strong>Thép D25:</strong> 3,850 kg/m &rarr; <strong>45,05 kg/cây 11,7m</strong> (22 cây/tấn)\n</div>\n\n<h2>1. Bảng tra trọng lượng thép xây dựng tròn từ D6 đến D32 chuẩn TCVN</h2>\n<p>Dưới đây là bảng tra cứu chi tiết khối lượng danh nghĩa theo tiêu chuẩn quốc gia <strong>TCVN 1651-1:2018</strong> (thép tròn trơn) và <strong>TCVN 1651-2:2018</strong> (thép thanh vằn). Chiều dài tiêu chuẩn của một cây thép thanh vằn xuất xưởng tại Việt Nam là <strong>11,7 mét</strong>.</p>\n\n<table>\n  <thead>\n    <tr>\n      <th>Ký Hiệu / Đường Kính</th>\n      <th>Dạng Thép Xuất Xưởng</th>\n      <th>Khối Lượng 1 Mét (kg/m)</th>\n      <th>Khối Lượng 1 Cây 11,7m (kg)</th>\n      <th>Số Cây Trên 1 Tấn (Cây/tấn)</th>\n      <th>Tiêu Chuẩn Áp Dụng</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Thép D6 (Phi 6)</strong></td>\n      <td>Cuộn tròn trơn</td>\n      <td>0,222</td>\n      <td>-</td>\n      <td>-</td>\n      <td>TCVN 1651-1:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D8 (Phi 8)</strong></td>\n      <td>Cuộn tròn trơn / Gân</td>\n      <td>0,395</td>\n      <td>4,62</td>\n      <td>216</td>\n      <td>TCVN 1651-1 / 1651-2</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D10 (Phi 10)</strong></td>\n      <td>Thanh vằn / Cuộn gân</td>\n      <td>0,617</td>\n      <td>7,22</td>\n      <td>138</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D12 (Phi 12)</strong></td>\n      <td>Thanh vằn (11,7m)</td>\n      <td>0,888</td>\n      <td>10,39</td>\n      <td>96</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D14 (Phi 14)</strong></td>\n      <td>Thanh vằn (11,7m)</td>\n      <td>1,210</td>\n      <td>14,16</td>\n      <td>70</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D16 (Phi 16)</strong></td>\n      <td>Thanh vằn (11,7m)</td>\n      <td>1,580</td>\n      <td>18,49</td>\n      <td>54</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D18 (Phi 18)</strong></td>\n      <td>Thanh vằn (11,7m)</td>\n      <td>2,000</td>\n      <td>23,40</td>\n      <td>42</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D20 (Phi 20)</strong></td>\n      <td>Thanh vằn (11,7m)</td>\n      <td>2,470</td>\n      <td>28,90</td>\n      <td>34</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D22 (Phi 22)</strong></td>\n      <td>Thanh vằn (11,7m)</td>\n      <td>2,980</td>\n      <td>34,87</td>\n      <td>28</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D25 (Phi 25)</strong></td>\n      <td>Thanh vằn (11,7m)</td>\n      <td>3,850</td>\n      <td>45,05</td>\n      <td>22</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D28 (Phi 28)</strong></td>\n      <td>Thanh vằn (11,7m)</td>\n      <td>4,830</td>\n      <td>56,51</td>\n      <td>17</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D32 (Phi 32)</strong></td>\n      <td>Thanh vằn (11,7m)</td>\n      <td>6,310</td>\n      <td>73,83</td>\n      <td>13</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. Công thức tính trọng lượng thép tròn xây dựng lý thuyết</h2>\n<p>Nếu không có bảng tra cứu bên cạnh, bạn có thể áp dụng công thức toán học rút gọn tiêu chuẩn sau:</p>\n<blockquote>\n  <strong>M = (D² / 162)</strong><br>\n  <em>Trong đó:</em><br>\n  - <strong>M:</strong> Khối lượng của 1 mét dài thanh thép (kg/m)<br>\n  - <strong>D:</strong> Đường kính danh nghĩa của thanh thép tính bằng milimet (mm)<br>\n  - <strong>162:</strong> Hằng số toán học thực nghiệm được chuẩn hóa từ khối lượng riêng của thép cacbon (7850 kg/m³).\n</blockquote>\n\n<p>Ví dụ tính khối lượng 1 cây thép D16 dài 11,7m:</p>\n<ul>\n  <li>Khối lượng 1m = (16 × 16) / 162 = 256 / 162 ≈ 1,580 kg/m.</li>\n  <li>Khối lượng 1 cây 11,7m = 1,580 × 11,7 ≈ 18,486 kg (làm tròn 18,49 kg).</li>\n</ul>\n\n<h2>3. Dung sai trọng lượng cho phép của các nhà máy thép</h2>\n<p>Trong thực tế sản xuất tại các nhà máy luyện kim (như Thép Hòa Phát, Việt Ý, Việt Đức, VAS, Pomina, TISCO), thép xuất xưởng sẽ có một tỷ lệ dung sai đường kính và khối lượng cho phép theo TCVN 1651:</p>\n<ul>\n  <li><strong>Đối với thép đường kính D6 đến D8:</strong> Dung sai khối lượng cho phép từ ±7% đến ±8%.</li>\n  <li><strong>Đối với thép đường kính D10 đến D14:</strong> Dung sai khối lượng cho phép từ ±5% đến ±6%.</li>\n  <li><strong>Đối với thép đường kính D16 đến D25:</strong> Dung sai khối lượng cho phép từ ±4% đến ±4,5%.</li>\n  <li><strong>Đối với thép đường kính D28 trở lên:</strong> Dung sai khối lượng cho phép khoảng ±3,5%.</li>\n</ul>\n<p>Điều này giải thích vì sao khi cân thực tế nguyên bó thép tại bàn cân điện tử công trình, trọng lượng thực tế (cân thực tế) có thể chênh lệch nhẹ so với trọng lượng tính toán theo barem lý thuyết (barem danh nghĩa).</p>\n\n<h2>4. Ứng dụng của từng loại đường kính thép trong công trình dân dụng</h2>\n<ul>\n  <li><strong>Thép D6, D8:</strong> Chủ yếu dùng làm thép đai (đai móng, đai cột, đai dầm), thép gia cường chống nứt bản sàn hoặc cấu kiện nhỏ.</li>\n  <li><strong>Thép D10, D12:</strong> Dùng làm cốt thép dọc cho sàn nhà dân dụng, lanh tô cửa, dầm phụ hoặc đai chịu lực lớn.</li>\n  <li><strong>Thép D14, D16, D18:</strong> Là cốt thép chịu lực chính cho cột nhà, dầm chính tầng trệt, móng đơn, móng băng cho nhà phố 2–4 tầng.</li>\n  <li><strong>Thép D20, D22, D25:</strong> Dùng làm kết cấu chịu lực lớn cho móng bè, móng cọc, khung dầm chuyển nhịp lớn hoặc các công trình biệt thự, khách sạn, nhà xưởng cao tầng.</li>\n</ul>\n\n<h2>5. Tham khảo danh mục Thép xây dựng tại VLXD Hoàng Yến</h2>\n<p>Nếu bạn đang chuẩn bị triển khai thi công công trình và cần tra cứu quy cách hoặc tìm hiểu các chủng loại thép thanh vằn, thép cuộn đang được lưu kho, bạn đọc có thể tham khảo thêm danh mục <a href="/thep-xay-dung/">Thép Xây Dựng</a> tại Siêu thị VLXD Hoàng Yến để xem đầy đủ các thương hiệu uy tín.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">TƯ VẤN KỸ THUẬT & BÁO GIÁ</div>\n    <h3 class="cta-heading">Cần Tư Vấn Quy Cách & Báo Giá Thép Xây Dựng Tại Quảng Trị?</h3>\n    <p class="cta-description">Quý khách hàng có thể gửi bảng thống kê cốt thép hoặc danh sách khối lượng dự kiến để Siêu thị VLXD Hoàng Yến hỗ trợ kiểm tra và báo giá xuất xưởng tốt nhất.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Gửi Bản Vẽ Qua Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>6. Câu hỏi thường gặp về trọng lượng thép xây dựng (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Chiều dài tiêu chuẩn của 1 cây thép thanh vằn xây dựng là bao nhiêu?</h3>\n  <div class="faq-answer"><p>Tại Việt Nam, chiều dài tiêu chuẩn của một cây thép thanh vằn (từ D10 đến D32) sản xuất theo TCVN 1651 là 11,7 mét (11.700 mm). Thép thường được bẻ gập đôi khi vận chuyển bằng xe tải nhỏ hoặc giữ thẳng nguyên cây trên xe mooc dài.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. 1 mét thép D10 nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Theo TCVN 1651-2:2018, 1 mét thép D10 có khối lượng danh nghĩa là 0,617 kg/m. Một cây dài 11,7m nặng khoảng 7,22 kg.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. 1 mét thép D16 nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Khối lượng danh nghĩa của 1 mét thép D16 là 1,580 kg/m. Một cây thép D16 dài 11,7 mét nặng khoảng 18,49 kg.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. 1 tấn thép D10 có khoảng bao nhiêu cây?</h3>\n  <div class="faq-answer"><p>1 tấn (1.000 kg) thép D10 có khoảng 138 cây tiêu chuẩn dài 11,7m (phép tính: 1.000 / 7,22 ≈ 138,5 cây).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. 1 tấn thép D16 có khoảng bao nhiêu cây?</h3>\n  <div class="faq-answer"><p>1 tấn thép D16 có khoảng 54 cây tiêu chuẩn dài 11,7m (phép tính: 1.000 / 18,49 ≈ 54,08 cây).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Thép phi 6 và phi 8 thường được bán theo cây hay theo kg?</h3>\n  <div class="faq-answer"><p>Thép D6 và D8 thông thường được sản xuất ở dạng cuộn tròn trơn nặng vài trăm kg/cuộn và được cân bán theo kg. Riêng thép D8 hiện nay một số nhà máy có thêm dạng thanh vằn thẳng cây 11,7m.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Vì sao trọng lượng cân thực tế lại khác với trọng lượng tính theo barem?</h3>\n  <div class="faq-answer"><p>Trọng lượng barem là trọng lượng danh nghĩa lý thuyết. Khi cán nóng tại nhà máy, các lô thép có dung sai cho phép theo TCVN (±3,5% đến ±8% tùy đường kính), do đó trọng lượng cân thực tế sẽ có sự chênh lệch nhỏ.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Mua thép xây dựng nên nghiệm thu theo hình thức đếm cây hay cân trọng lượng?</h3>\n  <div class="faq-answer"><p>Đối với thép cây thanh vằn (D10 - D32), công trình nhỏ thường nghiệm thu theo hình thức đếm số lượng cây theo barem; đối với công trình lớn thường kết hợp cân xe tải qua bàn cân điện tử để đối chiếu với hóa đơn xuất xưởng.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Ký hiệu dập nổi trên thân thanh thép có ý nghĩa gì?</h3>\n  <div class="faq-answer"><p>Trên thân cây thép thanh vằn luôn có dập nổi logo thương hiệu nhà sản xuất (ví dụ logo Hòa Phát), ký hiệu đường kính (ví dụ d16, d20) và ký hiệu mác thép (ví dụ CB3, CB4 hoặc dấu chấm nhận diện mác cường độ).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua thép xây dựng tại Đông Hà Quảng Trị ở đâu uy tín?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể liên hệ Siêu Thị VLXD Hoàng Yến tại số 299 Lê Duẩn, Phường Đông Hà, Quảng Trị (Hotline/Zalo: 0946.575.579) để kiểm tra chủng loại hàng hóa và nhận báo giá chi tiết.</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Bảng Trọng Lượng Thép Xây Dựng D6–D32 Chuẩn TCVN | VLXD Hoàng Yến', 'Bảng trọng lượng thép xây dựng D6, D8, D10, D12, D14, D16, D18, D20, D22, D25, D28, D32 theo TCVN 1651:2018. Tra cứu khối lượng mét và cây 11,7m chính xác.', 'thep-xay-dung', 'draft', '2026-09-16 12:15:39', '2026-09-16 12:15:39'),
(27, NULL, 'Công Thức & Cách Tính Trọng Lượng Thép Xây Dựng Tròn Chính Xác Nhất', 'cong-thuc-cach-tinh-trong-luong-thep', 'Hướng dẫn công thức tính trọng lượng thép xây dựng tròn trơn và thanh vằn theo mét và cây 11,7m. Giải thích nguồn gốc công thức M = D^2 / 162 và các ví dụ tính toán thực tế.', '\n<p>Trong quá trình thiết kế, bóc tách dự toán hoặc giám sát thi công, việc nắm vững công thức tính trọng lượng thép xây dựng giúp bạn chủ động kiểm tra khối lượng cốt thép mà không cần phụ thuộc vào bảng tra cứu.</p>\n\n<div class="callout-box">\n  <strong>Công thức tính nhanh trọng lượng thép tròn xây dựng (Chuẩn TCVN):</strong><br>\n  - <strong>Khối lượng 1 mét thép:</strong> <code>M = (D² / 162)</code> (kg/m)<br>\n  - <strong>Khối lượng 1 cây 11,7m:</strong> <code>M_cây = (D² / 162) × 11,7</code> (kg)<br>\n  - <strong>Số cây trên 1 tấn (1.000 kg):</strong> <code>N = 1.000 / M_cây</code> (cây)<br>\n  <em>Trong đó: D là đường kính thanh thép tính bằng mm (ví dụ: D10 thì D = 10, D16 thì D = 16).</em>\n</div>\n\n<h2>1. Nguồn gốc toán học của công thức tính trọng lượng thép tròn</h2>\n<p>Về mặt vật lý và hình học, một thanh thép tròn là một khối hình trụ tròn đặc. Khối lượng của thanh thép được tính theo công thức tổng quát:</p>\n<blockquote>\n  <strong>M = V × ρ = (S × L) × ρ</strong><br>\n  <em>Trong đó:</em><br>\n  - <strong>V:</strong> Thể tích khối thép (m³)<br>\n  - <strong>S:</strong> Diện tích mặt cắt ngang hình tròn: <code>S = π × r² = π × (d/2)² = (π × d²) / 4</code><br>\n  - <strong>L:</strong> Chiều dài thanh thép (m)<br>\n  - <strong>ρ:</strong> Khối lượng riêng của thép cacbon tiêu chuẩn = <strong>7.850 kg/m³</strong> (hoặc 0,00785 g/mm³).\n</blockquote>\n\n<p>Khi tính khối lượng cho <strong>1 mét dài (L = 1m = 1000mm)</strong> với đường kính danh nghĩa D tính bằng milimet (mm):</p>\n<blockquote>\n  <code>M = [3,14159 × (D² / 4) × 1000] × 7.850 × 10⁻⁹ ≈ (D² × 7850 × 3,14159) / 4.000.000</code><br>\n  <code>M ≈ D² × 0,00616537 = D² / (1 / 0,00616537) ≈ D² / 162,198</code>\n</blockquote>\n<p>Làm tròn mẫu số thực nghiệm trong ngành xây dựng, ta có công thức kinh điển: <strong>M = D² / 162</strong>.</p>\n\n<h2>2. Bảng tổng hợp công thức tính trọng lượng cho từng loại đường kính D6 đến D32</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Đường Kính (D)</th>\n      <th>Phép Tính 1 Mét (D² / 162)</th>\n      <th>Khối Lượng 1m (kg)</th>\n      <th>Phép Tính Cây 11,7m</th>\n      <th>Khối Lượng 1 Cây 11,7m (kg)</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>D6</strong></td><td>6² / 162 = 36 / 162</td><td>0,222 kg</td><td>0,222 × 11,7</td><td>2,60 kg</td></tr>\n    <tr><td><strong>D8</strong></td><td>8² / 162 = 64 / 162</td><td>0,395 kg</td><td>0,395 × 11,7</td><td>4,62 kg</td></tr>\n    <tr><td><strong>D10</strong></td><td>10² / 162 = 100 / 162</td><td>0,617 kg</td><td>0,617 × 11,7</td><td>7,22 kg</td></tr>\n    <tr><td><strong>D12</strong></td><td>12² / 162 = 144 / 162</td><td>0,888 kg</td><td>0,888 × 11,7</td><td>10,39 kg</td></tr>\n    <tr><td><strong>D14</strong></td><td>14² / 162 = 196 / 162</td><td>1,210 kg</td><td>1,210 × 11,7</td><td>14,16 kg</td></tr>\n    <tr><td><strong>D16</strong></td><td>16² / 162 = 256 / 162</td><td>1,580 kg</td><td>1,580 × 11,7</td><td>18,49 kg</td></tr>\n    <tr><td><strong>D18</strong></td><td>18² / 162 = 324 / 162</td><td>2,000 kg</td><td>2,000 × 11,7</td><td>23,40 kg</td></tr>\n    <tr><td><strong>D20</strong></td><td>20² / 162 = 400 / 162</td><td>2,470 kg</td><td>2,470 × 11,7</td><td>28,90 kg</td></tr>\n    <tr><td><strong>D22</strong></td><td>22² / 162 = 484 / 162</td><td>2,980 kg</td><td>2,980 × 11,7</td><td>34,87 kg</td></tr>\n    <tr><td><strong>D25</strong></td><td>25² / 162 = 625 / 162</td><td>3,850 kg</td><td>3,850 × 11,7</td><td>45,05 kg</td></tr>\n  </tbody>\n</table>\n\n<h2>3. Các bước tính toán tổng khối lượng cốt thép cho một hạng mục công trình</h2>\n<h3>Bước 1: Bóc tách chiều dài tổng cộng theo đường kính</h3>\n<p>Thống kê số thanh thép cùng đường kính từ bản vẽ kỹ thuật và nhân với chiều dài thanh để ra tổng số mét dài L_tong (m).</p>\n\n<h3>Bước 2: Áp dụng công thức khối lượng 1 mét dài</h3>\n<p>Lấy (D² / 162) để tìm ra trọng lượng của 1 mét thép tương ứng.</p>\n\n<h3>Bước 3: Nhân tổng chiều dài với trọng lượng 1 mét</h3>\n<p>Khối lượng tổng (kg) = L_tong × (D² / 162).</p>\n\n<h3>Bước 4: Tính hệ số nối chồng và hao hụt thi công (nếu cần)</h3>\n<p>Thông thường cộng thêm <strong>3% đến 5%</strong> hệ số nối thép và cắt đầu mẩu vụn cho công tác gia công tại hiện trường.</p>\n\n<h2>4. Ví dụ tính toán thực tế</h2>\n<p><strong>Bài toán:</strong> Một dầm bê tông cốt thép yêu cầu sử dụng 8 thanh thép D18, mỗi thanh có chiều dài thiết kế 8,5 mét. Hãy tính tổng khối lượng thép D18 cần dùng cho dầm này?</p>\n<ul>\n  <li>Tổng chiều dài thép D18: <code>L = 8 × 8,5 = 68 mét</code>.</li>\n  <li>Khối lượng 1 mét thép D18: <code>M = 18² / 162 = 324 / 162 = 2,00 kg/m</code>.</li>\n  <li>Tổng khối lượng lý thuyết: <code>Tổng kg = 68 × 2,00 = 136,0 kg</code>.</li>\n  <li>Nếu tính hao hụt gia công 3%: <code>136 × 1,03 = 140,08 kg</code>.</li>\n</ul>\n\n<h2>5. Tham khảo thêm về danh mục thép xây dựng tại VLXD Hoàng Yến</h2>\n<p>Bạn đọc có thể tra cứu chi tiết toàn bộ bảng tra từ D6 đến D32 tại bài viết <a href="/tin-tuc/bang-trong-luong-thep-xay-dung-d6-d32/">Bảng Trọng Lượng Thép Xây Dựng D6–D32</a> hoặc tham khảo danh mục <a href="/thep-xay-dung/">Thép Xây Dựng</a> tại VLXD Hoàng Yến.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">HỖ TRỢ DỰ TOÁN CỐT THÉP</div>\n    <h3 class="cta-heading">Cần Bóc Tách Khối Lượng Cốt Thép Bản Vẽ?</h3>\n    <p class="cta-description">Gửi bảng thống kê thép công trình của bạn cho Siêu thị VLXD Hoàng Yến để được tư vấn quy cách và lập dự toán vật tư chính xác nhất.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Tư Vấn Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>6. Câu hỏi thường gặp về công thức tính trọng lượng thép (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Con số 162 trong công thức D² / 162 từ đâu mà có?</h3>\n  <div class="faq-answer"><p>Số 162 là giá trị rút gọn từ phép toán (4.000.000) / (π × 7850) ≈ 162,198, xuất phát từ công thức tính thể tích hình trụ nhân với khối lượng riêng của thép cacbon 7850 kg/m³.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. Công thức D² / 162 có áp dụng được cho thép thanh vằn (có gân) không?</h3>\n  <div class="faq-answer"><p>Có. Công thức này áp dụng chính xác cho cả thép tròn trơn và thép thanh vằn vì đường kính D ở đây là đường kính danh nghĩa (diện tích mặt cắt danh nghĩa tương đương) theo quy định của TCVN 1651.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. Chiều dài tiêu chuẩn 1 cây thép xây dựng tại Việt Nam là bao nhiêu mét?</h3>\n  <div class="faq-answer"><p>Chiều dài tiêu chuẩn của một cây thép cây thanh vằn (D10 đến D32) xuất xưởng tại các nhà máy Việt Nam là 11,7 mét (11.700 mm).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. Làm thế nào để tính số cây thép trên 1 tấn?</h3>\n  <div class="faq-answer"><p>Bạn lấy 1.000 kg chia cho khối lượng của 1 cây thép 11,7m. Ví dụ với thép D10 (7,22 kg/cây): 1.000 / 7,22 ≈ 138 cây/tấn.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. Khối lượng riêng của thép xây dựng là bao nhiêu?</h3>\n  <div class="faq-answer"><p>Khối lượng riêng tiêu chuẩn của thép cacbon xây dựng theo TCVN là 7.850 kg/m³ (tương đương 7,85 g/cm³ hoặc 7,85 tấn/m³).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Sai số khối lượng thép thực tế so với công thức tính là bao nhiêu?</h3>\n  <div class="faq-answer"><p>Theo TCVN 1651, sai số khối lượng cho phép dao động từ ±3,5% đến ±8% tùy theo đường kính thép. Thép có đường kính càng lớn thì sai số cho phép càng nhỏ.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Khi nào nên dùng công thức tính nhanh, khi nào dùng bảng tra cứu?</h3>\n  <div class="faq-answer"><p>Công thức tính nhanh D² / 162 rất hữu ích khi bạn ở ngoài công trường và cần nhẩm nhanh trọng lượng của một thanh thép bất kỳ mà không có sổ tay bảng tra.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Thép hộp, thép hình có dùng được công thức D² / 162 không?</h3>\n  <div class="faq-answer"><p>Không. Công thức D² / 162 chỉ áp dụng cho thép tròn đặc. Thép hộp vuông, hộp chữ nhật hoặc thép hình U, I, V có công thức tính riêng dựa trên chu vi mặt cắt và độ dày thành thép.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Hệ số hao hụt thép khi cắt uốn cốt thép công trình thường là bao nhiêu?</h3>\n  <div class="faq-answer"><p>Trong định mức dự toán xây dựng cơ bản, hệ số hao hụt gia công cốt thép thường được tính từ 3% đến 5% đối với công trình dân dụng tiêu chuẩn.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua thép xây dựng chính hãng tại Quảng Trị ở đâu?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể liên hệ Siêu thị VLXD Hoàng Yến tại 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị (Hotline/Zalo: 0946.575.579) để nhận báo giá thép xây dựng cập nhật mới nhất.</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Công Thức Tính Trọng Lượng Thép Tròn Chuẩn Nhất | VLXD Hoàng Yến', 'Công thức tính trọng lượng thép xây dựng M = D^2 / 162. Hướng dẫn cách tính khối lượng thép tròn theo mét, cây 11,7m và số cây trên 1 tấn kèm ví dụ chi tiết.', 'thep-xay-dung', 'draft', '2026-09-16 12:15:39', '2026-09-16 12:15:39'),
(28, NULL, 'Thép D6 D8 Nặng Bao Nhiêu Kg? Trọng Lượng Thép Cuộn & Thép Cây Chuẩn', 'thep-d6-d8-nang-bao-nhieu-kg', 'Thép D6 và D8 nặng bao nhiêu kg? Trọng lượng 1 mét thép phi 6 là 0,222 kg/m, thép phi 8 là 0,395 kg/m theo TCVN 1651. Bảng quy đổi cuộn thép và ứng dụng thép đai.', '\n<p>Thép D6 (phi 6) và thép D8 (phi 8) là hai nhóm thép có đường kính nhỏ nhất trong nhóm thép xây dựng thô, chủ yếu được sản xuất ở dạng cuộn tròn trơn hoặc thanh gân để làm cốt thép đai chịu lực cắt và chống nứt kết cấu.</p>\n\n<div class="callout-box">\n  <strong>Trả lời nhanh trọng lượng thép D6 và D8 (Theo TCVN 1651-1 & 1651-2):</strong><br>\n  - <strong>Thép D6 (phi 6 tròn trơn):</strong> <strong>0,222 kg/m</strong> (1 kg ≈ 4,50 mét dài).<br>\n  - <strong>Thép D8 (phi 8 tròn trơn / thanh vằn):</strong> <strong>0,395 kg/m</strong> (1 kg ≈ 2,53 mét dài).<br>\n  - <strong>1 cây thép D8 tiêu chuẩn (11,7m):</strong> <strong>4,62 kg/cây</strong> (1 tấn có khoảng 216 cây).\n</div>\n\n<h2>1. Bảng quy cách và trọng lượng chi tiết của thép D6 và D8</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Chủng Loại</th>\n      <th>Đường Kính (mm)</th>\n      <th>Dạng Xuất Xưởng</th>\n      <th>Khối Lượng 1 Mét (kg)</th>\n      <th>Chiều Dài Của 1 Kg (m/kg)</th>\n      <th>Khối Lượng Cây 11,7m (kg)</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Thép D6 tròn trơn</strong></td>\n      <td>6 mm</td>\n      <td>Dạng cuộn (200 - 500kg/cuộn)</td>\n      <td>0,222</td>\n      <td>4,50</td>\n      <td>- (Không sản xuất cây)</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D8 tròn trơn</strong></td>\n      <td>8 mm</td>\n      <td>Dạng cuộn (200 - 500kg/cuộn)</td>\n      <td>0,395</td>\n      <td>2,53</td>\n      <td>4,62 (nếu cán thẳng)</td>\n    </tr>\n    <tr>\n      <td><strong>Thép D8 thanh vằn</strong></td>\n      <td>8 mm</td>\n      <td>Dạng thanh cây (11,7m)</td>\n      <td>0,395</td>\n      <td>2,53</td>\n      <td>4,62 kg/cây</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. Cách tính số mét dài từ khối lượng cân thực tế</h2>\n<p>Do thép D6 và D8 dạng cuộn thường được mua bán bằng hình thức cân ký (cân kg), việc tính ngược ra số mét dài rất quan trọng để người thợ ước lượng xem 1 cuộn thép bẻ được bao nhiêu chiếc đai cột hoặc đai dầm:</p>\n<blockquote>\n  - <strong>Số mét dài thép D6 = Khối lượng (kg) × 4,50</strong> (mét)<br>\n  - <strong>Số mét dài thép D8 = Khối lượng (kg) × 2,53</strong> (mét)<br>\n  <em>Ví dụ:</em> Bạn mua 50 kg thép D6 thì tổng chiều dài thép thu được xấp xỉ: <code>50 × 4,50 = 225 mét</code>.\n</blockquote>\n\n<h2>3. Ứng dụng chính của thép D6 và D8 trong công trình</h2>\n<ul>\n  <li><strong>Làm thép đai cột, đai dầm (Stirrup):</strong> Thép D6 và D8 được uốn thành các vòng đai hình vuông hoặc chữ nhật (ví dụ đai 150x150, 150x200, 200x200) để cố định vị trí các thanh thép chủ D14, D16, D18, đồng thời tăng cường khả năng chịu lực cắt cho dầm và cột bê tông cốt thép.</li>\n  <li><strong>Làm lưới thép đan sàn móng, sàn nhà:</strong> Thép D8 thường được đan thành lưới ô vuông a150x150 hoặc a200x200 cho lớp thép chịu lực sàn mái hoặc sàn tầng lầu trong nhà phố.</li>\n  <li><strong>Cấu kiện phụ trợ:</strong> Làm móc cẩu cấu kiện đúc sẵn, giằng tường, thép neo lanh tô cửa sổ và cửa đi.</li>\n</ul>\n\n<h2>4. Ví dụ tính số lượng đai bẻ được từ 1 cuộn thép D6 50kg</h2>\n<p><strong>Bài toán:</strong> Cần bẻ đai cột kích thước 150x200mm cho cột nhà. Chu vi 1 chiếc đai sau khi cộng đoạn móc câu bẻ gập là <code>(150 + 200) × 2 + 100 = 800mm = 0,8m</code>. Hỏi 50 kg thép D6 sẽ bẻ được khoảng bao nhiêu chiếc đai?</p>\n<ul>\n  <li>Tổng số mét dài của 50 kg thép D6: <code>50 × 4,50 = 225 mét</code>.</li>\n  <li>Số lượng đai bẻ được: <code>225 / 0,8 ≈ 281 chiếc đai</code>.</li>\n  <li>Trừ hao hụt cắt đầu mẩu 3%: Thực tế thu được khoảng <strong>272 chiếc đai hoàn chỉnh</strong>.</li>\n</ul>\n\n<h2>5. Tham khảo danh mục Thép xây dựng tại VLXD Hoàng Yến</h2>\n<p>Xem thêm <a href="/tin-tuc/bang-trong-luong-thep-xay-dung-d6-d32/">Bảng Trọng Lượng Thép D6 Đến D32</a> hoặc truy cập danh mục <a href="/thep-xay-dung/">Thép Xây Dựng</a> tại Siêu thị VLXD Hoàng Yến để cập nhật nguồn hàng.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">GIAO THÉP TẬN NƠI</div>\n    <h3 class="cta-heading">Cần Mua Thép Cuộn D6, D8 Hòa Phát Tại Quảng Trị?</h3>\n    <p class="cta-description">VLXD Hoàng Yến cung cấp thép cuộn D6, D8 bốc dỡ tận nơi, cam kết cân đúng tải trọng và đầy đủ tem mác xuất xưởng của nhà máy.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Zalo Tư Vấn</a>\n    </div>\n  </div>\n</div>\n\n<h2>6. Câu hỏi thường gặp về thép D6 và D8 (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Thép D6 nặng bao nhiêu kg trên 1 mét?</h3>\n  <div class="faq-answer"><p>Theo TCVN 1651-1:2018, khối lượng danh nghĩa của 1 mét thép D6 là 0,222 kg/m.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. Thép D8 nặng bao nhiêu kg trên 1 mét?</h3>\n  <div class="faq-answer"><p>Khối lượng danh nghĩa của 1 mét thép D8 là 0,395 kg/m theo TCVN 1651.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. 1 kg thép D6 dài bao nhiêu mét?</h3>\n  <div class="faq-answer"><p>1 kg thép D6 có chiều dài xấp xỉ 4,50 mét (1 / 0,222 ≈ 4,504m).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. 1 kg thép D8 dài bao nhiêu mét?</h3>\n  <div class="faq-answer"><p>1 kg thép D8 có chiều dài xấp xỉ 2,53 mét (1 / 0,395 ≈ 2,531m).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. 1 cây thép D8 dài 11,7m nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Một cây thép D8 dạng thanh vằn thẳng dài 11,7m có khối lượng là 4,62 kg (phép tính: 0,395 × 11,7 = 4,6215 kg).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. 1 tấn thép D8 có bao nhiêu cây 11,7m?</h3>\n  <div class="faq-answer"><p>1 tấn (1.000 kg) thép D8 cây thẳng tương đương khoảng 216 cây (1.000 / 4,62 ≈ 216,4 cây).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Thép D6 có sản xuất dạng thanh cây dài 11,7m không?</h3>\n  <div class="faq-answer"><p>Không. Do đường kính nhỏ và độ mềm dẻo cao, thép D6 tại tất cả các nhà máy thép Việt Nam chỉ sản xuất ở dạng cuộn tròn trơn.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. 1 cuộn thép D6 hoặc D8 nặng khoảng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Một cuộn thép D6 hoặc D8 xuất xưởng từ nhà máy nặng từ 200 kg đến 500 kg/cuộn (thậm chí có cuộn lớn đến 1.000 kg). Tại các cửa hàng VLXD thường hỗ trợ cắt xả cuộn nhỏ theo yêu cầu của khách hàng.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Làm thép đai cột nhà dân dụng nên dùng D6 hay D8?</h3>\n  <div class="faq-answer"><p>Đối với nhà cấp 4 và nhà 1–2 tầng chịu tải trọng nhỏ, thợ thường dùng đai thép D6. Đối với nhà 3 tầng trở lên hoặc dầm nhịp lớn, các kỹ sư kết cấu thường chỉ định dùng đai thép D8 để đảm bảo an toàn chịu lực cắt.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua thép D6 D8 tại Đông Hà Quảng Trị ở đâu uy tín?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể mua thép D6, D8 tại Siêu thị VLXD Hoàng Yến tại 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị (Hotline/Zalo: 0946.575.579).</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Thép D6 D8 Nặng Bao Nhiêu Kg? Barem Thép Cuộn & Cây | VLXD Hoàng Yến', 'Thép D6 nặng 0,222 kg/m, thép D8 nặng 0,395 kg/m. 1 cây thép D8 dài 11,7m nặng 4,62 kg. Tra cứu quy cách thép cuộn tròn trơn, thép đai xây dựng chuẩn xác.', 'thep-xay-dung', 'draft', '2026-09-16 12:15:39', '2026-09-16 12:15:39'),
(29, NULL, 'Thép D10 Nặng Bao Nhiêu Kg? 1 Cây Thép D10 Dài 11,7m Nặng Bao Nhiêu?', 'thep-d10-nang-bao-nhieu-kg', 'Thép D10 nặng bao nhiêu kg? Trọng lượng 1 mét thép D10 là 0,617 kg/m và 1 cây 11,7m nặng 7,22 kg theo TCVN 1651. 1 tấn thép D10 có 138 cây tiêu chuẩn.', '\n<p>Thép D10 (thép phi 10 thanh vằn) là loại thép kết cấu được sử dụng nhiều nhất trong các hạng mục đổ bê tông bản sàn, đan lưới móng và lanh tô dầm phụ cho mọi công trình nhà ở dân dụng.</p>\n\n<div class="callout-box">\n  <strong>Trả lời nhanh trọng lượng thép D10 (Theo TCVN 1651-2:2018):</strong><br>\n  - <strong>Khối lượng 1 mét thép D10:</strong> <strong>0,617 kg/m</strong><br>\n  - <strong>Khối lượng 1 cây tiêu chuẩn (11,7m):</strong> <strong>7,22 kg/cây</strong> (chính xác: 7,2189 kg)<br>\n  - <strong>1 tấn thép D10 có khoảng:</strong> <strong>138 cây</strong> (1.000 / 7,22 ≈ 138,5 cây).\n</div>\n\n<h2>1. Bảng quy cách tiêu chuẩn của thép D10</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Thông Số</th>\n      <th>Giá Trị Danh Nghĩa</th>\n      <th>Đơn Vị Tính</th>\n      <th>Tiêu Chuẩn Áp Dụng</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Đường kính danh nghĩa</strong></td>\n      <td>10</td>\n      <td>mm</td>\n      <td>TCVN 1651-2:2018</td>\n    </tr>\n    <tr>\n      <td><strong>Diện tích mặt cắt danh nghĩa</strong></td>\n      <td>78,54</td>\n      <td>mm²</td>\n      <td>π × 10² / 4</td>\n    </tr>\n    <tr>\n      <td><strong>Khối lượng 1 mét dài</strong></td>\n      <td>0,617</td>\n      <td>kg/m</td>\n      <td>Chuẩn TCVN</td>\n    </tr>\n    <tr>\n      <td><strong>Chiều dài cây tiêu chuẩn</strong></td>\n      <td>11,7</td>\n      <td>m</td>\n      <td>11.700 mm</td>\n    </tr>\n    <tr>\n      <td><strong>Khối lượng 1 cây 11,7m</strong></td>\n      <td>7,22</td>\n      <td>kg</td>\n      <td>0,617 × 11,7 = 7,2189 kg</td>\n    </tr>\n    <tr>\n      <td><strong>Số cây trên 1 tấn</strong></td>\n      <td>138</td>\n      <td>cây</td>\n      <td>Làm tròn</td>\n    </tr>\n    <tr>\n      <td><strong>Dung sai khối lượng cho phép</strong></td>\n      <td>±6,0%</td>\n      <td>%</td>\n      <td>Theo TCVN 1651</td>\n    </tr>\n    <tr>\n      <td><strong>Mác thép phổ biến</strong></td>\n      <td>CB240-T, CB300-V</td>\n      <td>-</td>\n      <td>Cuộn gân hoặc cây vằn</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. Ứng dụng quan trọng của thép D10 trong xây dựng nhà ở</h2>\n<ul>\n  <li><strong>Cốt thép bản sàn (Sàn bê tông toàn khối):</strong> Đan lưới thép sàn 2 lớp (lớp dưới chịu mô men dương nhịp sàn, lớp trên chịu mô men âm gối dầm) với khoảng cách đan thông thường a120x120mm hoặc a150x150mm.</li>\n  <li><strong>Lưới thép móng đơn, móng băng:</strong> Làm lớp thép phân bố hoặc thép chịu lực phụ cho móng nhà cấp 4, nhà 1–2 tầng.</li>\n  <li><strong>Thép gia cường lanh tô và ô văng:</strong> Đặt trong các dầm giằng tường, lanh tô cửa đi, lanh tô cửa sổ và ban công nhô ra ngoài.</li>\n  <li><strong>Thép đai cho dầm, cột tiết diện lớn:</strong> Trong các công trình dầm nhịp lớn đòi hỏi khả năng kháng cắt cao.</li>\n</ul>\n\n<h2>3. Ví dụ tính khối lượng thép D10 cần dùng cho sàn nhà 100m2</h2>\n<p><strong>Bài toán:</strong> Cần đan thép sàn 2 lớp cho diện tích sàn 100m2 bằng thép D10, khoảng cách ô đan a150x150mm. Định mức ước tính khoảng <strong>12 kg thép D10/m2 sàn</strong>. Hãy tính tổng số cây thép D10 cần mua?</p>\n<ul>\n  <li>Tổng khối lượng thép D10: <code>100 m² × 12 kg/m² = 1.200 kg = 1,2 tấn</code>.</li>\n  <li>Số cây thép D10 (mỗi cây 7,22 kg): <code>1.200 / 7,22 ≈ 166,2 cây</code>.</li>\n  <li>Cộng hao hụt cắt nối 3%: Dự toán cần đặt mua khoảng <strong>172 cây thép D10</strong>.</li>\n</ul>\n\n<h2>4. Tham khảo danh mục Thép xây dựng tại VLXD Hoàng Yến</h2>\n<p>Xem thêm bài viết <a href="/tin-tuc/cong-thuc-cach-tinh-trong-luong-thep/">Công Thức Tính Trọng Lượng Thép</a> hoặc danh mục <a href="/thep-xay-dung/">Thép Xây Dựng</a> tại Siêu thị VLXD Hoàng Yến.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">GIAO HÀNG TẬN CÔNG TRÌNH</div>\n    <h3 class="cta-heading">Cần Đặt Mua Thép D10 Hòa Phát Tại Quảng Trị?</h3>\n    <p class="cta-description">Siêu thị VLXD Hoàng Yến phân phối thép thanh vằn D10 chính hãng, hỗ trợ kiểm đếm số cây rõ ràng và vận chuyển nhanh chóng tại Đông Hà.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Zalo Báo Giá</a>\n    </div>\n  </div>\n</div>\n\n<h2>5. Câu hỏi thường gặp về thép D10 (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Thép D10 nặng bao nhiêu kg trên 1 mét?</h3>\n  <div class="faq-answer"><p>Khối lượng 1 mét thép D10 theo chuẩn TCVN 1651 là 0,617 kg/m.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. 1 cây thép D10 dài 11,7m nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Một cây thép D10 dài 11,7m có khối lượng danh nghĩa là 7,22 kg.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. 1 tấn thép D10 có bao nhiêu cây?</h3>\n  <div class="faq-answer"><p>1 tấn (1.000 kg) thép D10 có khoảng 138 cây dài 11,7m.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. 1 bó thép D10 nguyên đai nhà máy gồm bao nhiêu cây?</h3>\n  <div class="faq-answer"><p>Thông thường tại các nhà máy như Hòa Phát, 1 bó thép D10 được đóng gói từ 250 đến 350 cây/bó tùy theo lô sản xuất, tổng trọng lượng khoảng 1,8 đến 2,5 tấn/bó.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. Thép D10 có dạng cuộn không hay chỉ có dạng cây thẳng?</h3>\n  <div class="faq-answer"><p>Thép D10 có cả hai dạng: dạng thanh vằn thẳng cây dài 11,7m (phổ biến nhất cho công trình dân dụng) và dạng cuộn gân (thường dùng cho các máy nắn duỗi tự động tại các xưởng gia công lớn).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Đan thép sàn nhà nên chọn khoảng cách a150 hay a200?</h3>\n  <div class="faq-answer"><p>Khoảng cách phụ thuộc vào tính toán nhịp sàn và chiều dày bản sàn của kỹ sư thiết kế. Thông thường bản sàn nhà dân dụng dày 100mm dùng thép D10 đan a150x150mm (đối với lớp dưới) và a150x150mm hoặc a200x200mm (lớp trên).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Thép D10 mác CB300-V có ý nghĩa gì?</h3>\n  <div class="faq-answer"><p>Ký hiệu "CB300-V" biểu thị đây là thép thanh vằn (chữ V) có giới hạn chảy tối thiểu là 300 N/mm² (MPa), đạt tiêu chuẩn cường độ thi công kết cấu theo TCVN 1651-2.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Dấu hiệu nhận biết thép D10 thật trên công trường?</h3>\n  <div class="faq-answer"><p>Thân thép có gân xoắn nổi đều, màu xanh đen ánh kim loại của thép cán nóng, dập nổi logo thương hiệu rõ nét kèm ký hiệu "d10" và tem nhãn treo ở đầu bó thép.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Giá 1 cây thép D10 được tính như thế nào?</h3>\n  <div class="faq-answer"><p>Giá 1 cây thép D10 = (Đơn giá thép/kg tại thời điểm mua) × 7,22 kg.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua thép D10 tại Đông Hà Quảng Trị ở đâu?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể liên hệ Siêu thị VLXD Hoàng Yến tại 299 Lê Duẩn, Phường Đông Hà, Quảng Trị hoặc gọi Hotline/Zalo 0946.575.579.</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Thép D10 Nặng Bao Nhiêu Kg? Trọng Lượng Cây 11,7m Chuẩn | VLXD Hoàng Yến', 'Thép D10 nặng 0,617 kg/m. 1 cây thép D10 dài 11,7m nặng 7,22 kg. 1 tấn thép D10 có 138 cây. Bảng quy cách, ứng dụng thép phi 10 đan sàn móng nhà chuẩn xác.', 'thep-xay-dung', 'draft', '2026-09-16 12:15:39', '2026-09-16 12:15:39'),
(30, NULL, 'Thép D12 D14 Nặng Bao Nhiêu Kg? Trọng Lượng Cây 11,7m & Số Cây/Tấn', 'thep-d12-d14-nang-bao-nhieu-kg', 'Thép D12 và D14 nặng bao nhiêu kg? Khối lượng 1m thép D12 là 0,888 kg/m (10,39 kg/cây 11,7m) và thép D14 là 1,210 kg/m (14,16 kg/cây 11,7m). Bảng tra cứu chuẩn TCVN.', '\n<p>Thép D12 (phi 12) và thép D14 (phi 14) là hai loại thép thanh vằn trung gian, đóng vai trò cốt thép chịu lực chính cho hệ dầm phụ, lanh tô gối chịu tải và cốt thép cột cho các công trình nhà ở 1 đến 3 tầng.</p>\n\n<div class="callout-box">\n  <strong>Trả lời nhanh trọng lượng thép D12 và D14 (Theo TCVN 1651-2:2018):</strong><br>\n  - <strong>Thép D12 (phi 12):</strong> <strong>0,888 kg/m</strong> &rarr; <strong>10,39 kg/cây 11,7m</strong> (1 tấn có khoảng <strong>96 cây</strong>).<br>\n  - <strong>Thép D14 (phi 14):</strong> <strong>1,210 kg/m</strong> &rarr; <strong>14,16 kg/cây 11,7m</strong> (1 tấn có khoảng <strong>70 cây</strong>).\n</div>\n\n<h2>1. Bảng so sánh quy cách và khối lượng thép D12 và D14</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Thông Số Kỹ Thuật</th>\n      <th>Thép D12 (Phi 12)</th>\n      <th>Thép D14 (Phi 14)</th>\n      <th>Đơn Vị Tính</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Đường kính danh nghĩa</strong></td>\n      <td>12</td>\n      <td>14</td>\n      <td>mm</td>\n    </tr>\n    <tr>\n      <td><strong>Diện tích mặt cắt danh nghĩa</strong></td>\n      <td>113,1</td>\n      <td>153,9</td>\n      <td>mm²</td>\n    </tr>\n    <tr>\n      <td><strong>Khối lượng 1 mét dài</strong></td>\n      <td>0,888</td>\n      <td>1,210</td>\n      <td>kg/m</td>\n    </tr>\n    <tr>\n      <td><strong>Chiều dài cây tiêu chuẩn</strong></td>\n      <td>11,7</td>\n      <td>11,7</td>\n      <td>m</td>\n    </tr>\n    <tr>\n      <td><strong>Khối lượng 1 cây 11,7m</strong></td>\n      <td>10,39</td>\n      <td>14,16</td>\n      <td>kg/cây</td>\n    </tr>\n    <tr>\n      <td><strong>Số cây trên 1 tấn (1.000 kg)</strong></td>\n      <td>96</td>\n      <td>70</td>\n      <td>cây/tấn</td>\n    </tr>\n    <tr>\n      <td><strong>Dung sai khối lượng cho phép</strong></td>\n      <td>±5,0%</td>\n      <td>±5,0%</td>\n      <td>%</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. Ứng dụng thực tế của thép D12 và D14 trong công trình</h2>\n<ul>\n  <li><strong>Thép D12:</strong> Thường dùng làm cốt thép dọc dầm phụ, dầm giằng tường móng, cốt thép chịu lực sàn gánh tải lớn hoặc cốt chủ cột góc nhà cấp 4.</li>\n  <li><strong>Thép D14:</strong> Thường dùng làm cốt thép chủ cho hệ cột nhà 1–2 tầng, cốt thép dọc dầm chính tầng lầu nhịp ngắn dưới 4 mét, hoặc lưới thép đài móng băng.</li>\n</ul>\n\n<h2>3. Tham khảo danh mục Thép xây dựng tại VLXD Hoàng Yến</h2>\n<p>Xem thêm <a href="/tin-tuc/bang-trong-luong-thep-xay-dung-d6-d32/">Bảng Trọng Lượng Thép D6 Đến D32</a> hoặc truy cập danh mục <a href="/thep-xay-dung/">Thép Xây Dựng</a> tại VLXD Hoàng Yến.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">BÁO GIÁ THÉP TẠI QUẢNG TRỊ</div>\n    <h3 class="cta-heading">Cần Tư Vấn & Mua Thép D12, D14 Tại Đông Hà?</h3>\n    <p class="cta-description">Siêu thị VLXD Hoàng Yến cung ứng thép thanh vằn D12, D14 chuẩn TCVN, hỗ trợ giao tận chân công trình tại Quảng Trị.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Liên Hệ Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>4. Câu hỏi thường gặp về thép D12 và D14 (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. 1 mét thép D12 nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Theo TCVN 1651-2:2018, 1 mét thép D12 nặng 0,888 kg/m.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. 1 cây thép D12 dài 11,7m nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Một cây thép D12 dài 11,7m nặng khoảng 10,39 kg (0,888 × 11,7 = 10,3896 kg).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. 1 mét thép D14 nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Theo TCVN 1651-2:2018, 1 mét thép D14 nặng 1,210 kg/m.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. 1 cây thép D14 dài 11,7m nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Một cây thép D14 dài 11,7m nặng khoảng 14,16 kg (1,210 × 11,7 = 14,157 kg).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. 1 tấn thép D12 có bao nhiêu cây?</h3>\n  <div class="faq-answer"><p>1 tấn (1.000 kg) thép D12 có khoảng 96 cây tiêu chuẩn 11,7m (1.000 / 10,39 ≈ 96,2 cây).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. 1 tấn thép D14 có bao nhiêu cây?</h3>\n  <div class="faq-answer"><p>1 tấn (1.000 kg) thép D14 có khoảng 70 cây tiêu chuẩn 11,7m (1.000 / 14,16 ≈ 70,6 cây).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. 1 bó thép D12 nguyên đai nhà máy nặng bao nhiêu tấn?</h3>\n  <div class="faq-answer"><p>Tại nhà máy Hòa Phát, 1 bó thép D12 thường đóng gói khoảng 200 đến 300 cây/bó, tổng trọng lượng bó khoảng 2,0 đến 3,1 tấn.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Nhà cấp 4 gác lửng nên dùng thép D12 hay D14 làm cột?</h3>\n  <div class="faq-answer"><p>Thông thường hệ cột chịu lực tầng trệt nhà có gác lửng nên sử dụng 4 cây thép D14 để đảm bảo khả năng chịu nén và chống uốn dọc, các cột phụ hoặc giằng tường có thể dùng D12.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Ký hiệu dập trên thép D12 và D14 như thế nào?</h3>\n  <div class="faq-answer"><p>Trên thân thanh thép có dập nổi logo thương hiệu nhà sản xuất, chữ số "d12" hoặc "d14" và ký hiệu mác thép tương ứng.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Địa chỉ mua thép D12 D14 tại Đông Hà Quảng Trị?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể liên hệ Siêu thị VLXD Hoàng Yến tại 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị (Hotline/Zalo: 0946.575.579).</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Thép D12 D14 Nặng Bao Nhiêu Kg? Barem Chuẩn TCVN | VLXD Hoàng Yến', 'Thép D12 nặng 0,888 kg/m (10,39 kg/cây). Thép D14 nặng 1,210 kg/m (14,16 kg/cây). 1 tấn thép D12 có 96 cây, D14 có 70 cây. Tra cứu bảng barem thép xây dựng chuẩn.', 'thep-xay-dung', 'draft', '2026-09-16 12:15:39', '2026-09-16 12:15:39'),
(31, NULL, 'Thép D18 D20 Nặng Bao Nhiêu Kg? Quy Cách & Trọng Lượng Thép Cây Lớn', 'thep-d18-d20-nang-bao-nhieu-kg', 'Thép D18 và D20 nặng bao nhiêu kg? Trọng lượng 1m thép D18 là 2,00 kg/m (23,40 kg/cây 11,7m) và thép D20 là 2,47 kg/m (28,90 kg/cây 11,7m) theo TCVN 1651.', '\n<p>Thép D18 (phi 18) và thép D20 (phi 20) thuộc nhóm cốt thép chịu lực lớn, chuyên dụng cho các cấu kiện móng bè, móng cọc, khung dầm vượt nhịp lớn và cột chịu tải trọng nặng của nhà phố nhiều tầng, biệt thự hoặc nhà xưởng công nghiệp.</p>\n\n<div class="callout-box">\n  <strong>Trả lời nhanh trọng lượng thép D18 và D20 (Theo TCVN 1651-2:2018):</strong><br>\n  - <strong>Thép D18 (phi 18):</strong> <strong>2,000 kg/m</strong> &rarr; <strong>23,40 kg/cây 11,7m</strong> (1 tấn có khoảng <strong>42 cây</strong>).<br>\n  - <strong>Thép D20 (phi 20):</strong> <strong>2,470 kg/m</strong> &rarr; <strong>28,90 kg/cây 11,7m</strong> (1 tấn có khoảng <strong>34 cây</strong>).\n</div>\n\n<h2>1. Bảng quy cách kỹ thuật chi tiết của thép D18 và D20</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Thông Số Kỹ Thuật</th>\n      <th>Thép D18 (Phi 18)</th>\n      <th>Thép D20 (Phi 20)</th>\n      <th>Đơn Vị Tính</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Đường kính danh nghĩa</strong></td>\n      <td>18</td>\n      <td>20</td>\n      <td>mm</td>\n    </tr>\n    <tr>\n      <td><strong>Diện tích mặt cắt danh nghĩa</strong></td>\n      <td>254,5</td>\n      <td>314,2</td>\n      <td>mm²</td>\n    </tr>\n    <tr>\n      <td><strong>Khối lượng 1 mét dài</strong></td>\n      <td>2,000</td>\n      <td>2,470</td>\n      <td>kg/m</td>\n    </tr>\n    <tr>\n      <td><strong>Chiều dài cây tiêu chuẩn</strong></td>\n      <td>11,7</td>\n      <td>11,7</td>\n      <td>m</td>\n    </tr>\n    <tr>\n      <td><strong>Khối lượng 1 cây 11,7m</strong></td>\n      <td>23,40</td>\n      <td>28,90</td>\n      <td>kg/cây</td>\n    </tr>\n    <tr>\n      <td><strong>Số cây trên 1 tấn (1.000 kg)</strong></td>\n      <td>42</td>\n      <td>34</td>\n      <td>cây/tấn</td>\n    </tr>\n    <tr>\n      <td><strong>Dung sai khối lượng cho phép</strong></td>\n      <td>±4,0%</td>\n      <td>±4,0%</td>\n      <td>%</td>\n    </tr>\n    <tr>\n      <td><strong>Mác thép khuyến nghị</strong></td>\n      <td>CB400-V, CB500-V</td>\n      <td>CB400-V, CB500-V</td>\n      <td>-</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. Ứng dụng thực tế của thép D18 và D20</h2>\n<ul>\n  <li><strong>Cốt thép cột chịu lực:</strong> Sử dụng làm cốt chủ cho các cột nhà phố từ 3–5 tầng, cột khung nhà xưởng chịu tải cầu trục.</li>\n  <li><strong>Cốt thép dầm chuyển và dầm nhịp lớn:</strong> Bố trí ở lớp dưới chịu kéo và lớp trên gối tựa của các dầm có khẩu độ vượt nhịp từ 5 mét đến 8 mét.</li>\n  <li><strong>Móng cọc và móng băng chịu tải lớn:</strong> Bố trí trong các đài móng cọc ép, móng cọc khoan nhồi hoặc móng bè toàn khối.</li>\n</ul>\n\n<h2>3. Tham khảo danh mục Thép xây dựng tại VLXD Hoàng Yến</h2>\n<p>Xem thêm <a href="/tin-tuc/bang-trong-luong-thep-xay-dung-d6-d32/">Bảng Trọng Lượng Thép Xây Dựng Từ D6 Đến D32</a> hoặc tham khảo danh mục <a href="/thep-xay-dung/">Thép Xây Dựng</a> tại VLXD Hoàng Yến.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">GIAO THÉP CÔNG TRÌNH</div>\n    <h3 class="cta-heading">Cần Đặt Mua Thép D18, D20 Hòa Phát Tại Quảng Trị?</h3>\n    <p class="cta-description">Siêu thị VLXD Hoàng Yến cung cấp thép cây D18, D20 đầy đủ chứng chỉ chất lượng CO/CQ từ nhà máy, hỗ trợ cẩu hạ hàng tận công trình.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Báo Giá Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>4. Câu hỏi thường gặp về thép D18 và D20 (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. 1 mét thép D18 nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Theo TCVN 1651-2:2018, 1 mét thép D18 có khối lượng danh nghĩa tròn là 2,000 kg/m.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. 1 cây thép D18 dài 11,7m nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Một cây thép D18 dài 11,7m nặng 23,40 kg (phép tính: 2,000 × 11,7 = 23,40 kg).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. 1 mét thép D20 nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Theo TCVN 1651-2:2018, 1 mét thép D20 nặng 2,470 kg/m.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. 1 cây thép D20 dài 11,7m nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Một cây thép D20 dài 11,7m nặng khoảng 28,90 kg (phép tính: 2,470 × 11,7 = 28,899 kg).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. 1 tấn thép D18 có bao nhiêu cây?</h3>\n  <div class="faq-answer"><p>1 tấn (1.000 kg) thép D18 có khoảng 42 cây dài 11,7m (1.000 / 23,40 ≈ 42,7 cây).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. 1 tấn thép D20 có bao nhiêu cây?</h3>\n  <div class="faq-answer"><p>1 tấn (1.000 kg) thép D20 có khoảng 34 cây dài 11,7m (1.000 / 28,90 ≈ 34,6 cây).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Thép D18 và D20 thường được đóng gói bao nhiêu cây 1 bó?</h3>\n  <div class="faq-answer"><p>Tại nhà máy Hòa Phát, 1 bó thép D18 thường có 100 cây/bó (nặng ~2,34 tấn); 1 bó thép D20 thường có 100 cây/bó (nặng ~2,89 tấn).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Đoạn nối chồng tiêu chuẩn cho thép D20 là bao nhiêu mét?</h3>\n  <div class="faq-answer"><p>Theo TCVN 5574, đoạn nối buộc thép chịu kéo tối thiểu từ 30d đến 40d (với d=20mm, đoạn nối dài từ 600mm đến 800mm, tương đương 0,6m đến 0,8m).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Ký hiệu dập nổi trên thân cây thép D20 Hòa Phát là gì?</h3>\n  <div class="faq-answer"><p>Thân cây thép D20 có dập nổi logo 3 tam giác Hòa Phát, chữ số "d20" và dấu chấm nhận diện mác thép (CB3, CB4 hoặc CB5).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua thép D18 D20 tại Đông Hà Quảng Trị ở đâu?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể liên hệ Siêu thị VLXD Hoàng Yến tại số 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị (Hotline/Zalo: 0946.575.579).</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Thép D18 D20 Nặng Bao Nhiêu Kg? Trọng Lượng Cây 11,7m Chuẩn | VLXD Hoàng Yến', 'Thép D18 nặng 2,00 kg/m (23,40 kg/cây). Thép D20 nặng 2,47 kg/m (28,90 kg/cây). 1 tấn thép D18 có 42 cây, D20 có 34 cây. Bảng tra cứu barem thép lớn chuẩn.', 'thep-xay-dung', 'draft', '2026-09-16 12:15:39', '2026-09-16 12:15:39'),
(32, NULL, 'Phân Biệt Thép Cuộn Và Thép Cây Thanh Vằn Trong Xây Dựng', 'phan-biet-thep-cuon-va-thep-cay-thanh-van', 'Phân biệt thép cuộn tròn trơn và thép cây thanh vằn: Khái niệm, quy cách đóng gói, đặc tính chịu lực và vị trí ứng dụng trong thi công nhà ở dân dụng.', '\n<p>Trong ngành vật liệu xây dựng thô, thép cốt bê tông được chia thành hai nhóm sản phẩm cơ bản nhất: <strong>thép cuộn</strong> (thép tròn trơn/gân cuộn) và <strong>thép cây</strong> (thép thanh vằn). Việc hiểu rõ đặc tính của từng loại giúp chủ nhà và thợ thi công bố trí đúng vị trí kết cấu.</p>\n\n<div class="callout-box">\n  <strong>Tóm tắt điểm khác biệt cốt lõi:</strong><br>\n  - <strong>Thép cuộn:</strong> Dạng cuộn tròn liền mạch (200 - 500kg/cuộn), đường kính D6, D8, D10, bề mặt trơn nhẵn hoặc có gân nhỏ. Ứng dụng làm thép đai, lưới đan sàn, giằng tường.<br>\n  - <strong>Thép cây (thanh vằn):</strong> Dạng thanh thẳng dài tiêu chuẩn 11,7m, đường kính D10 đến D32, bề mặt có gân vằn xoắn nổi cao. Ứng dụng làm cốt thép chịu lực chính cho móng, cột, dầm.\n</div>\n\n<h2>1. Bảng so sánh chi tiết giữa Thép Cuộn và Thép Cây</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Tiêu Chí So Sánh</th>\n      <th>Thép Cuộn (Wire Rod)</th>\n      <th>Thép Cây Thanh Vằn (Rebar)</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Hình thức xuất xưởng</strong></td>\n      <td>Dạng cuộn tròn nguyên khối</td>\n      <td>Dạng cây thẳng (thanh) dài 11,7 mét</td>\n    </tr>\n    <tr>\n      <td><strong>Đường kính phổ biến</strong></td>\n      <td>Phi 6 (D6), Phi 8 (D8), Phi 10 (D10)</td>\n      <td>Phi 10, 12, 14, 16, 18, 20, 22, 25, 28, 32</td>\n    </tr>\n    <tr>\n      <td><strong>Bề mặt thanh thép</strong></td>\n      <td>Tròn trơn nhẵn (hoặc gân nổi nhẹ)</td>\n      <td>Có gân xoắn (thanh vằn) hình xương cá</td>\n    </tr>\n    <tr>\n      <td><strong>Mục đích tạo gân vằn</strong></td>\n      <td>Dễ nắn thẳng, dễ uốn đai góc hẹp</td>\n      <td>Tăng ma sát và lực bám dính tối đa với bê tông</td>\n    </tr>\n    <tr>\n      <td><strong>Mác thép thông dụng</strong></td>\n      <td>CB240-T, CB300-T</td>\n      <td>CB300-V, CB400-V, CB500-V</td>\n    </tr>\n    <tr>\n      <td><strong>Cách thức mua bán</strong></td>\n      <td>Cân trọng lượng (kg / tấn)</td>\n      <td>Đếm số lượng cây theo barem hoặc cân xe tải</td>\n    </tr>\n    <tr>\n      <td><strong>Vị trí ứng dụng chính</strong></td>\n      <td>Thép đai cột dầm, thép chống nứt sàn</td>\n      <td>Cốt chủ chịu lực kéo/nén cho móng, cột, dầm</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. Vì sao thép cây bắt buộc phải có gân vằn (gai xoắn)?</h2>\n<p>Bê tông là vật liệu chịu nén rất tốt nhưng chịu kéo rất kém. Ngược lại, thép có khả năng chịu lực kéo tuyệt vời. Khi kết hợp thành bê tông cốt thép, các đường gân vằn nổi trên thân cây thép đóng vai trò tạo ngàm liên kết cơ học, ngăn không cho thanh thép bị tuột hoặc trượt dọc trong khối bê tông khi công trình chịu tải trọng uốn hoặc rung động.</p>\n\n<h2>3. Tham khảo danh mục Thép xây dựng tại VLXD Hoàng Yến</h2>\n<p>Xem thêm bài viết <a href="/tin-tuc/bang-trong-luong-thep-xay-dung-d6-d32/">Bảng Trọng Lượng Thép D6 Đến D32</a> hoặc truy cập danh mục <a href="/thep-xay-dung/">Thép Xây Dựng</a> tại VLXD Hoàng Yến.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">PHÂN PHỐI THÉP CHÍNH HÃNG</div>\n    <h3 class="cta-heading">Cần Tư Vấn Cốt Thép Cho Công Trình Tại Quảng Trị?</h3>\n    <p class="cta-description">Siêu thị VLXD Hoàng Yến cung ứng đầy đủ các loại thép cuộn D6, D8 và thép cây D10 - D32 từ các thương hiệu lớn như Hòa Phát, Việt Ý, VAS.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Tư Vấn Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>4. Câu hỏi thường gặp về phân biệt thép cuộn và thép cây (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Thép tròn trơn và thép thanh vằn khác nhau ở điểm nào rõ nhất?</h3>\n  <div class="faq-answer"><p>Điểm khác biệt rõ nhất là bề mặt: Thép tròn trơn có bề mặt nhẵn bóng không có gân; thép thanh vằn có các gân nổi hình xương cá hoặc gân xoắn chạy dọc thân cây.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. Thép D10 có dạng cuộn hay dạng cây thẳng?</h3>\n  <div class="faq-answer"><p>Thép D10 có cả hai dạng: Thép D10 cây thẳng thanh vằn dài 11,7m và thép D10 cuộn gân.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. Có thể dùng thép tròn trơn thay thế thép thanh vằn làm cốt chủ cột được không?</h3>\n  <div class="faq-answer"><p>Không nên. Thép tròn trơn có độ bám dính ma sát với bê tông thấp hơn rất nhiều so với thép thanh vằn, do đó không đảm bảo an toàn chịu lực cho các cấu kiện cột dầm chịu tải chính.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. 1 cuộn thép xây dựng nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Một cuộn thép xuất xưởng từ nhà máy nặng từ 200kg đến 500kg (cuộn nhỏ) hoặc 700kg đến 1.000kg (cuộn lớn phục vụ công nghiệp).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. Chiều dài tiêu chuẩn 1 cây thép thanh vằn là bao nhiêu mét?</h3>\n  <div class="faq-answer"><p>Chiều dài tiêu chuẩn của 1 cây thép thanh vằn tại Việt Nam là 11,7 mét.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Thép cuộn được bảo quản tại công trình như thế nào để tránh gỉ sét?</h3>\n  <div class="faq-answer"><p>Thép cuộn cần được kê trên đà gỗ hoặc pallet cách mặt đất tối thiểu 15–20cm, che bạt chống mưa ẩm và tránh tiếp xúc trực tiếp với bùn đất hoặc hóa chất ăn mòn.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Ký hiệu chữ T và chữ V trong mác thép có ý nghĩa gì?</h3>\n  <div class="faq-answer"><p>Chữ "T" viết tắt của Tròn trơn (ví dụ CB240-T); chữ "V" viết tắt của thanh Vằn (ví dụ CB300-V, CB400-V) theo tiêu chuẩn TCVN 1651.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Khi vận chuyển thép cây 11,7m vào ngõ nhỏ thì làm thế nào?</h3>\n  <div class="faq-answer"><p>Tại nhà máy hoặc kho đại lý, các cây thép 11,7m có thể được bẻ gập đôi (thành hình chữ U dài khoảng 5,85m) để xe tải nhỏ 2,5 - 5 tấn dễ dàng luồn lách vào các ngõ ngách công trình dân dụng.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Có thể duỗi thẳng thép cuộn bằng phương pháp thủ công không?</h3>\n  <div class="faq-answer"><p>Có. Thợ xây thường dùng tời kéo hoặc cọc neo thủ công để kéo thẳng thép cuộn D6, D8 trước khi đo cắt và bẻ đai.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua thép cuộn và thép cây tại Đông Hà Quảng Trị ở đâu?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể liên hệ Siêu thị VLXD Hoàng Yến tại 299 Lê Duẩn, Phường Đông Hà, Quảng Trị hoặc gọi Hotline/Zalo 0946.575.579.</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Phân Biệt Thép Cuộn Và Thép Cây Thanh Vằn | VLXD Hoàng Yến', 'So sánh chi tiết thép cuộn tròn trơn (D6, D8, D10) và thép cây thanh vằn (D10 - D32). Khác biệt về quy cách, mác thép và ứng dụng trong bê tông cốt thép.', 'thep-xay-dung', 'draft', '2026-09-16 12:15:39', '2026-09-16 12:15:39'),
(33, NULL, 'Mác Thép CB240-T, CB300-V, CB400-V, CB500-V Là Gì? Ý Nghĩa & So Sánh', 'mac-thep-cb240-cb300-cb400-cb500', 'Mác thép CB240, CB300, CB400, CB500 là gì? Ý nghĩa ký hiệu, giới hạn chảy, độ bền kéo và sự khác biệt giữa các mác thép xây dựng theo chuẩn TCVN 1651.', '\n<p>Trên thân các thanh thép xây dựng xuất xưởng từ các nhà máy luôn dập nổi các ký hiệu mác thép như CB3, CB4 hoặc các chấm nhận diện. Mác thép là chỉ số kỹ thuật phản ánh cường độ chịu lực và độ dẻo của thanh thép.</p>\n\n<div class="callout-box">\n  <strong>Giải thích nhanh ký hiệu mác thép theo TCVN 1651:2018:</strong><br>\n  - <strong>C (Cấp):</strong> Cốt bê tông.<br>\n  - <strong>B (Bền):</strong> Cấp độ bền của thép.<br>\n  - <strong>Số (240, 300, 400, 500):</strong> Giới hạn chảy tối thiểu của thanh thép tính bằng <strong>N/mm² (hoặc MPa)</strong>.<br>\n  - <strong>Chữ T:</strong> Thép tròn Trơn (ví dụ: CB240-T).<br>\n  - <strong>Chữ V:</strong> Thép thanh Vằn có gân (ví dụ: CB300-V, CB400-V, CB500-V).\n</div>\n\n<h2>1. Bảng so sánh chỉ tiêu cơ lý của các mác thép theo TCVN 1651</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Mác Thép</th>\n      <th>Dạng Bề Mặt</th>\n      <th>Giới Hạn Chảy Tối Thiểu (Re)</th>\n      <th>Độ Bền Kéo Tối Thiểu (Rm)</th>\n      <th>Độ Giãn Dài Sau Đứt (A5)</th>\n      <th>Ứng Dụng Điển Hình</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>CB240-T</strong></td>\n      <td>Tròn trơn</td>\n      <td>240 N/mm² (MPa)</td>\n      <td>380 N/mm²</td>\n      <td>≥ 20%</td>\n      <td>Thép đai D6, D8, cốt thép cấu tạo</td>\n    </tr>\n    <tr>\n      <td><strong>CB300-V</strong></td>\n      <td>Thanh vằn</td>\n      <td>300 N/mm² (MPa)</td>\n      <td>450 N/mm²</td>\n      <td>≥ 16%</td>\n      <td>Nhà ở dân dụng thấp tầng (1–3 tầng)</td>\n    </tr>\n    <tr>\n      <td><strong>CB400-V</strong></td>\n      <td>Thanh vằn</td>\n      <td>400 N/mm² (MPa)</td>\n      <td>570 N/mm²</td>\n      <td>≥ 14%</td>\n      <td>Nhà phố cao tầng (3–7 tầng), nhà xưởng</td>\n    </tr>\n    <tr>\n      <td><strong>CB500-V</strong></td>\n      <td>Thanh vằn</td>\n      <td>500 N/mm² (MPa)</td>\n      <td>650 N/mm²</td>\n      <td>≥ 12%</td>\n      <td>Công trình nhịp lớn, chung cư cao tầng, cầu đường</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. So sánh mác thép CB300-V và CB400-V</h2>\n<p>Đây là hai mác thép được sử dụng phổ biến nhất trong xây dựng dân dụng hiện nay:</p>\n<ul>\n  <li><strong>Về cường độ:</strong> Mác CB400-V có giới hạn chảy cao hơn 33% so với CB300-V (400 MPa so với 300 MPa). Nhờ cường độ chịu kéo cao hơn, việc dùng thép CB400-V cho phép tiết kiệm số lượng thanh thép trong cùng một tiết diện dầm cột.</li>\n  <li><strong>Về độ dẻo dai:</strong> Mác CB300-V có độ giãn dài cao hơn một chút, giúp thợ uốn nắn các góc móc neo dễ dàng hơn tại công trường thủ công.</li>\n</ul>\n\n<h2>3. Tham khảo danh mục Thép xây dựng tại VLXD Hoàng Yến</h2>\n<p>Xem thêm bài viết <a href="/tin-tuc/bang-trong-luong-thep-xay-dung-d6-d32/">Bảng Trọng Lượng Thép D6 Đến D32</a> hoặc tham khảo danh mục <a href="/thep-xay-dung/">Thép Xây Dựng</a> tại VLXD Hoàng Yến.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">TƯ VẤN MÁC THÉP THIẾT KẾ</div>\n    <h3 class="cta-heading">Cần Tư Vấn Chọn Mác Thép Cho Bản Vẽ Kết Cấu?</h3>\n    <p class="cta-description">Siêu thị VLXD Hoàng Yến cung ứng đầy đủ các mác thép CB240-T, CB300-V, CB400-V, CB500-V chính hãng từ Hòa Phát tại Quảng Trị.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Tư Vấn Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>4. Câu hỏi thường gặp về mác thép xây dựng (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Chữ "CB" trong mác thép viết tắt của từ gì?</h3>\n  <div class="faq-answer"><p>Chữ "CB" là viết tắt của "Cốt Bê tông" theo quy chuẩn ký hiệu tiêu chuẩn Việt Nam TCVN 1651.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. Con số 300 hoặc 400 trong mác thép có ý nghĩa gì?</h3>\n  <div class="faq-answer"><p>Con số 300 hay 400 thể hiện giới hạn chảy tối thiểu của vật liệu thép tính bằng đơn vị N/mm² (Newton trên milimet vuông), tương đương đơn vị MPa (Megapascal).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. Giới hạn chảy của thép là gì?</h3>\n  <div class="faq-answer"><p>Giới hạn chảy là mức ứng suất mà tại đó vật liệu thép bắt đầu bị biến dạng dẻo vĩnh viễn (không thể đàn hồi trở lại hình dạng ban đầu) khi chịu lực kéo.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. Mác thép CB300 và CB400 loại nào đắt hơn?</h3>\n  <div class="faq-answer"><p>Thông thường đơn giá trên 1 kg của thép mác CB400-V chỉ chênh lệch rất nhẹ (khoảng vài chục đồng đến một trăm đồng/kg) hoặc tương đương với CB300-V tùy theo chính sách giá từng thời điểm của nhà máy.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. Xây nhà 2 tầng nên dùng mác thép CB300 hay CB400?</h3>\n  <div class="faq-answer"><p>Đối với nhà ở dân dụng 1–3 tầng, mác thép CB300-V hoặc CB400-V đều đáp ứng rất tốt yêu cầu an toàn chịu lực. Bạn nên đối chiếu theo đúng chỉ định trong hồ sơ thiết kế kết cấu của kỹ sư.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Dấu chấm dập nổi trên thân thép Hòa Phát thể hiện điều gì?</h3>\n  <div class="faq-answer"><p>Trên thân thép thanh vằn Hòa Phát, số lượng dấu chấm dập nổi thể hiện mác thép: 1 chấm biểu thị mác CB300-V, 2 chấm biểu thị mác CB400-V, 3 chấm biểu thị mác CB500-V.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Thép mác CB500 có uốn bẻ đai dễ dàng không?</h3>\n  <div class="faq-answer"><p>Thép CB500 có cường độ chịu lực rất cao nên độ cứng lớn hơn, khi uốn bẻ góc gắt cần máy uốn cơ học công suất lớn và bán kính uốn tiêu chuẩn lớn hơn để tránh rạn nứt thép.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Tiêu chuẩn TCVN 1651 là gì?</h3>\n  <div class="faq-answer"><p>TCVN 1651 là bộ Tiêu chuẩn Quốc gia Việt Nam quy định yêu cầu kỹ thuật đối với thép cốt bê tông (Phần 1: Thép tròn trơn, Phần 2: Thép thanh vằn).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Trọng lượng của thép CB300 và CB400 có khác nhau không?</h3>\n  <div class="faq-answer"><p>Không. Cùng một đường kính danh nghĩa (ví dụ D16), khối lượng 1 mét của thép mác CB300 và CB400 đều bằng nhau là 1,58 kg/m.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua thép xây dựng đầy đủ mác CB300, CB400 tại Quảng Trị ở đâu?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể liên hệ Siêu thị VLXD Hoàng Yến tại 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị (Hotline/Zalo: 0946.575.579).</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Mác Thép CB240 CB300 CB400 CB500 Là Gì? Ý Nghĩa Chuẩn TCVN | VLXD Hoàng Yến', 'Giải thích ý nghĩa mác thép CB240-T, CB300-V, CB400-V, CB500-V theo TCVN 1651:2018. So sánh giới hạn chảy, độ bền kéo và cách chọn mác thép xây nhà.', 'thep-xay-dung', 'draft', '2026-09-16 12:15:39', '2026-09-16 12:15:39'),
(34, NULL, 'Xây Nhà Dùng Thép D Bao Nhiêu? Cách Chọn Thép Móng, Cột, Dầm, Sàn', 'xay-nha-dung-thep-d-bao-nhieu', 'Xây nhà dân dụng nên dùng thép D bao nhiêu cho móng, cột, dầm, sàn? Hướng dẫn chi tiết cách chọn đường kính cốt thép cho nhà cấp 4, nhà phố 2 tầng, 3 tầng.', '\n<p>Lựa chọn đúng đường kính thép (D) cho từng cấu kiện kết cấu không chỉ đảm bảo an toàn chịu lực lâu dài cho ngôi nhà mà còn giúp gia chủ tối ưu hóa chi phí đầu tư, tránh lãng phí vật tư.</p>\n\n<div class="callout-box">\n  <strong>Tóm tắt đường kính thép tiêu chuẩn cho nhà ở dân dụng (1–3 tầng):</strong><br>\n  - <strong>Thép bản sàn nhà:</strong> D10 (đan lưới ô vuông a150x150mm).<br>\n  - <strong>Thép đai cột, đai dầm:</strong> D6 hoặc D8 (khoảng cách đai a100 - a200mm).<br>\n  - <strong>Thép cốt chủ Cột:</strong> D14, D16, D18 (bố trí 4 cây hoặc 6 cây).<br>\n  - <strong>Thép cốt chủ Dầm:</strong> D14, D16, D18, D20 (kết hợp thép chịu mô men âm và dương).<br>\n  - <strong>Thép đài móng, móng băng:</strong> D12, D14, D16 (đan lưới chịu lực đáy móng).\n</div>\n\n<h2>1. Bảng hướng dẫn chọn đường kính cốt thép theo từng hạng mục công trình</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Hạng Mục Cấu Kiện</th>\n      <th>Nhà Cấp 4 / 1 Tầng</th>\n      <th>Nhà Phố 2 – 3 Tầng</th>\n      <th>Nhà Phố 4 – 5 Tầng</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Cốt thép đài móng</strong></td>\n      <td>D10 – D12 (a150)</td>\n      <td>D12 – D14 (a150)</td>\n      <td>D14 – D16 (a120)</td>\n    </tr>\n    <tr>\n      <td><strong>Cốt thép dầm móng (giằng)</strong></td>\n      <td>4 cây D14</td>\n      <td>4 – 6 cây D16 / D18</td>\n      <td>6 cây D18 / D20</td>\n    </tr>\n    <tr>\n      <td><strong>Cốt thép chủ Cột</strong></td>\n      <td>4 cây D14</td>\n      <td>4 – 6 cây D16 / D18</td>\n      <td>6 – 8 cây D18 / D20</td>\n    </tr>\n    <tr>\n      <td><strong>Cốt thép chủ Dầm sàn</strong></td>\n      <td>4 cây D14 / D16</td>\n      <td>4 – 6 cây D16 / D18</td>\n      <td>6 cây D18 / D20</td>\n    </tr>\n    <tr>\n      <td><strong>Cốt thép bản Sàn</strong></td>\n      <td>D8 – D10 (a150)</td>\n      <td>D10 (a150)</td>\n      <td>D10 (a120)</td>\n    </tr>\n    <tr>\n      <td><strong>Cốt thép đai (Cột, Dầm)</strong></td>\n      <td>D6 (a150 - a200)</td>\n      <td>D6 – D8 (a100 - a200)</td>\n      <td>D8 (a100 - a150)</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. Những nguyên tắc cốt lõi khi bố trí cốt thép trong bê tông</h2>\n<ul>\n  <li><strong>Lớp bê tông bảo vệ:</strong> Khoảng cách từ mép ngoài thanh thép đến mép ngoài bê tông tối thiểu là 15mm (đối với bản sàn), 20mm (đối với dầm cột) và 30–50mm (đối với móng tiếp xúc đất) để chống rỉ sét.</li>\n  <li><strong>Chiều dài đoạn nối buộc:</strong> Đoạn nối chồng thép chịu kéo tối thiểu bằng <strong>30d đến 40d</strong> (ví dụ: thép D16 nối tối thiểu <code>40 × 16 = 640mm = 0,64m</code>).</li>\n  <li><strong>Vị trí nối thép:</strong> Không nối quá 50% số lượng thanh thép trên cùng một mặt cắt; đối với dầm, không nối thép lớp dưới ở giữa bụng dầm và không nối thép lớp trên ở vị trí gối cột.</li>\n</ul>\n\n<h2>3. Tham khảo danh mục Thép xây dựng tại VLXD Hoàng Yến</h2>\n<p>Xem thêm bài viết <a href="/tin-tuc/bang-trong-luong-thep-xay-dung-d6-d32/">Bảng Trọng Lượng Thép D6 Đến D32</a> hoặc tham khảo danh mục <a href="/thep-xay-dung/">Thép Xây Dựng</a> tại VLXD Hoàng Yến.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">HỖ TRỢ TƯ VẤN VẬT TƯ</div>\n    <h3 class="cta-heading">Cần Tư Vấn Bóc Tách Khối Lượng Thép Cho Ngôi Nhà Mới?</h3>\n    <p class="cta-description">Gửi bản vẽ mặt bằng kiến trúc hoặc bản vẽ kết cấu cho Siêu thị VLXD Hoàng Yến để được hỗ trợ tính toán số lượng cây và báo giá chi tiết.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Tư Vấn Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>4. Câu hỏi thường gặp khi chọn thép xây nhà (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Xây nhà 2 tầng nông thôn nên dùng thép cột phi bao nhiêu?</h3>\n  <div class="faq-answer"><p>Thông thường nhà 2 tầng kết cấu khung bê tông cốt thép sử dụng cột tiết diện 200x200mm hoặc 220x220mm với 4 cây thép D16 hoặc 4 cây D18 mác CB300/CB400.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. Thép sàn nên dùng D8 hay D10?</h3>\n  <div class="faq-answer"><p>Đối với sàn nhà dân dụng hiện đại đổ bê tông dày 100mm, đa số các kỹ sư kết cấu chỉ định sử dụng thép D10 đan ô vuông a150x150mm để tăng cường độ cứng và chống võng nứt sàn hiệu quả hơn D8.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. Nhà cấp 4 mái tôn có cần đổ cột bê tông bằng thép D16 không?</h3>\n  <div class="faq-answer"><p>Nhà cấp 4 mái tôn có tải trọng mái nhẹ, thông thường hệ cột chỉ cần sử dụng 4 cây thép D14 là đã đảm bảo độ an toàn chịu lực.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. Cốt thép đai cột nên đặt dày ở vị trí nào?</h3>\n  <div class="faq-answer"><p>Cốt thép đai cột nên được bố trí dày hơn (khoảng cách a100mm) ở vị trí đầu cột và chân cột (trong phạm vi chiều cao khoảng 500mm tính từ mặt sàn hoặc dầm) để kháng lực cắt uốn cục bộ.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. 1m2 sàn xây dựng cần khoảng bao nhiêu kg thép?</h3>\n  <div class="faq-answer"><p>Chỉ số tiêu hao cốt thép thông thường cho nhà ở dân dụng dao động từ <strong>25 kg đến 35 kg thép/m2 sàn xây dựng</strong> (tính tổng cộng cho toàn bộ móng, cột, dầm, sàn, lanh tô).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Thép bị rỉ sét màu vàng đỏ nhẹ có dùng để đổ bê tông được không?</h3>\n  <div class="faq-answer"><p>Thép mới bị rỉ bề mặt dạng bụi phấn mỏng do tiếp xúc không khí ẩm vẫn sử dụng tốt, chỉ cần dùng bàn chải sắt hoặc giẻ lau sạch bụi rỉ trước khi đổ bê tông. Nếu thép bị rỉ bong vảy sâu làm giảm tiết diện thanh thép thì không được dùng cho kết cấu chịu lực chính.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Thép cây có nối bằng phương pháp hàn thay vì buộc dây kẽm được không?</h3>\n  <div class="faq-answer"><p>Đối với thép xây dựng thông thường, nối buộc bằng dây kẽm 1 ly là phương pháp phổ biến và an toàn nhất. Việc hàn điện tại công trường chỉ được áp dụng khi có chỉ định của kỹ sư kết cấu và dùng que hàn chuyên dụng để tránh làm giòn gãy cục bộ thanh thép.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Cục kê bê tông bảo vệ cốt thép có vai trò gì?</h3>\n  <div class="faq-answer"><p>Cục kê bê tông định vị khoảng cách giữa cốt thép và cốp pha, đảm bảo lớp bê tông bảo vệ bao bọc kín thanh thép, ngăn chặn không khí ẩm và nước ngấm làm rỉ sét cốt thép bên trong.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Nhà phố liền kề móng lệch tâm nên dùng thép móng phi bao nhiêu?</h3>\n  <div class="faq-answer"><p>Móng chân vịt (móng lệch tâm) chịu mô men uốn lệch tâm lớn nên dầm móng giằng khóa đầu cột thường phải sử dụng thép đường kính lớn như D18, D20 hoặc D22.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua thép xây dựng uy tín tại Đông Hà Quảng Trị ở đâu?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể liên hệ Siêu thị VLXD Hoàng Yến tại 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị hoặc gọi Hotline/Zalo 0946.575.579.</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Xây Nhà Dùng Thép D Bao Nhiêu? Cách Chọn Thép Móng Cột Dầm Sàn | VLXD Hoàng Yến', 'Hướng dẫn chọn đường kính thép xây nhà dân dụng: Móng dùng thép D12-D16, Cột dùng D14-D20, Dầm dùng D14-D20, Sàn dùng D10, Đai dùng D6-D8 chuẩn kỹ thuật.', 'thep-xay-dung', 'draft', '2026-09-16 12:15:39', '2026-09-16 12:15:39'),
(35, NULL, 'Bảng Báo Giá Thép Xây Dựng Tại Quảng Trị Mới Nhất Hôm Nay', 'gia-thep-xay-dung-tai-quang-tri', 'Bảng báo giá thép xây dựng Hòa Phát, Việt Ý, VAS tại Đông Hà, Quảng Trị mới nhất. Thông tin các yếu tố ảnh hưởng đến đơn giá thép thanh vằn và thép cuộn.', '\n<p>Thép xây dựng là một trong những loại vật tư chiếm tỷ trọng ngân sách lớn nhất trong tổng chi phí xây thô ngôi nhà. Đơn giá sắt thép trên thị trường biến động liên tục theo giá phôi thép và nguyên liệu thế giới.</p>\n\n<div class="callout-box">\n  <strong>Lưu ý về đơn giá thép xây dựng:</strong><br>\n  Giá thép xây dựng thực tế phụ thuộc vào thương hiệu (Hòa Phát, VAS, Việt Ý, Việt Đức), số lượng đặt hàng (mua lẻ theo cây hay mua theo tấn cho công trình), địa điểm giao nhận và cự ly vận chuyển. Quý khách hàng vui lòng liên hệ trực tiếp để nhận bảng giá xuất xưởng chính xác tại thời điểm mua.\n</div>\n\n<h2>1. Các thương hiệu thép xây dựng uy tín phân phối tại Quảng Trị</h2>\n<p>Tại thị trường tỉnh Quảng Trị và khu vực miền Trung, các thương hiệu thép cán nóng tiêu chuẩn được các chủ đầu tư và nhà thầu tin dùng hàng đầu bao gồm:</p>\n<ul>\n  <li><strong>Thép Hòa Phát:</strong> Thương hiệu dẫn đầu thị phần Việt Nam với công nghệ lò cao liên hợp hiện đại, chất lượng cơ lý ổn định đạt chuẩn TCVN 1651 và ASTM.</li>\n  <li><strong>Thép VAS (Việt Mỹ):</strong> Sản phẩm có chất lượng phôi thép tốt, độ dẻo cao và giá thành cạnh tranh cho công trình dân dụng.</li>\n  <li><strong>Thép Việt Ý / Việt Đức:</strong> Được sử dụng nhiều trong các dự án hạ tầng và nhà xưởng cao tầng.</li>\n</ul>\n\n<h2>2. Các yếu tố ảnh hưởng trực tiếp đến giá thép xây dựng tại Đông Hà</h2>\n<ol>\n  <li><strong>Chủng loại và quy cách thép:</strong> Thép cuộn D6, D8 tròn trơn và thép cây thanh vằn D10 - D32 có barem và đơn giá/kg tương ứng.</li>\n  <li><strong>Mác thép cường độ:</strong> Các mác thép cường độ cao như CB400-V, CB500-V thường có sự chênh lệch nhẹ so với mác CB300-V.</li>\n  <li><strong>Khối lượng đơn hàng:</strong> Đơn hàng số lượng lớn (xe tải 10–25 tấn) giao thẳng từ nhà máy luôn có chính sách giá xuất xưởng tối ưu hơn đơn hàng mua lẻ vài chục cây.</li>\n  <li><strong>Chi phí vận chuyển & cẩu hạ hàng:</strong> Khoảng cách từ tổng kho 299 Lê Duẩn, Đông Hà đến các địa bàn như Cam Lộ, Triệu Phong, Gio Linh, Cửa Việt.</li>\n</ol>\n\n<h2>3. Quy trình đặt mua và giao nhận thép tại VLXD Hoàng Yến</h2>\n<ul>\n  <li><strong>Bước 1: Tiếp nhận danh sách:</strong> Khách hàng gửi bản thống kê cốt thép hoặc bảng kê khối lượng qua Hotline/Zalo 0946.575.579.</li>\n  <li><strong>Bước 2: Báo giá & Chốt đơn:</strong> Đội ngũ nhân viên Hoàng Yến kiểm tra tồn kho, gửi báo giá chi tiết kèm thời gian giao hàng.</li>\n  <li><strong>Bước 3: Vận chuyển & Giao nhận:</strong> Xe tải có gắn cẩu chuyên dụng chở thép đến tận chân công trình.</li>\n  <li><strong>Bước 4: Kiểm đếm & Nghiệm thu:</strong> Chủ nhà hoặc đại diện công trình đồng kiểm tra số lượng cây theo barem hoặc phiếu cân điện tử.</li>\n</ul>\n\n<h2>4. Tham khảo danh mục Thép xây dựng tại VLXD Hoàng Yến</h2>\n<p>Quý khách hàng có thể xem bảng quy chuẩn trọng lượng tại bài viết <a href="/tin-tuc/bang-trong-luong-thep-xay-dung-d6-d32/">Bảng Trọng Lượng Thép D6 Đến D32</a> hoặc truy cập danh mục sản phẩm <a href="/thep-xay-dung/">Thép Xây Dựng</a>.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">BÁO GIÁ TRỰC TIẾP TẠI KHO</div>\n    <h3 class="cta-heading">Nhận Báo Giá Thép Xây Dựng Hôm Nay Tại Quảng Trị</h3>\n    <p class="cta-description">Gửi khối lượng dự kiến của công trình để Siêu thị VLXD Hoàng Yến báo giá cạnh tranh nhất và tư vấn tiến độ cấp hàng an toàn.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Báo Giá Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>5. Câu hỏi thường gặp về giá thép xây dựng tại Quảng Trị (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Giá thép xây dựng tại Quảng Trị được tính theo cây hay theo kg?</h3>\n  <div class="faq-answer"><p>Cả hai hình thức đều được áp dụng: Đối với khách hàng mua số lượng lớn hoặc công trình dự án, giá thường được tính theo đơn giá kg (hoặc tấn); đối với khách hàng mua lẻ, cửa hàng quy đổi ra giá bán theo từng cây thép 11,7m theo barem trọng lượng tiêu chuẩn.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. Làm thế nào để tính giá của 1 cây thép thanh vằn?</h3>\n  <div class="faq-answer"><p>Giá 1 cây thép = (Đơn giá thép/kg) × (Khối lượng 1 cây theo barem TCVN). Ví dụ: Cây thép D16 nặng 18,49 kg, lấy 18,49 nhân với đơn giá/kg tại thời điểm mua.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. VLXD Hoàng Yến có hỗ trợ giao thép tận chân công trình tại các huyện lân cận không?</h3>\n  <div class="faq-answer"><p>Có. Chúng tôi có đội xe tải chuyên dụng hỗ trợ vận chuyển thép đến các khu vực tại TP. Đông Hà, Huyện Cam Lộ, Triệu Phong, Gio Linh, Cửa Việt và các địa bàn lân cận trong tỉnh Quảng Trị.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. Giá thép xây dựng có bao gồm thuế VAT chưa?</h3>\n  <div class="faq-answer"><p>Bảng báo giá của Siêu thị VLXD Hoàng Yến luôn có thể xuất hóa đơn VAT đầy đủ theo đúng quy định pháp luật cho các công ty, nhà thầu và khách hàng cá nhân có nhu cầu.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. Mua thép số lượng bao nhiêu thì được tính giá sỉ công trình?</h3>\n  <div class="faq-answer"><p>Khách hàng đặt mua thép theo khối lượng gói xây thô trọn gói hoặc từ 3–5 tấn trở lên sẽ được áp dụng chính sách giá ưu đãi theo khối lượng dự án.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Có nên mua toàn bộ thép xây nhà một lần hay mua theo từng giai đoạn thi công?</h3>\n  <div class="faq-answer"><p>Nếu công trình có mặt bằng bãi chứa khô ráo rộng rãi và dự báo giá thép có xu hướng tăng, gia chủ có thể đặt mua một lần. Nếu mặt bằng chật hẹp, nên đặt mua theo từng đợt (đợt móng, đợt thân cột dầm sàn tầng 1, đợt tầng 2) để tránh thép bị rỉ sét do mưa nắng.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Dấu hiệu nhận biết thép Hòa Phát chính hãng khi nhận hàng?</h3>\n  <div class="faq-answer"><p>Thép Hòa Phát có logo 3 hình tam giác dập nổi kèm chữ "HOA PHAT", ký hiệu đường kính và mác thép rõ nét trên thân cây, bó thép có tem nhãn mã vạch truy xuất nguồn gốc rõ ràng.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Khi nhận thép tại công trường cần kiểm tra những gì?</h3>\n  <div class="faq-answer"><p>Cần kiểm tra: (1) Đúng thương hiệu và quy cách đặt mua; (2) Số lượng cây thép hoặc phiếu cân điện tử xe tải; (3) Bề mặt thép không bị rỉ bong vảy hoặc nứt gãy; (4) Phiếu xuất kho của nhà phân phối.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Bảng báo giá thép có hiệu lực trong bao lâu?</h3>\n  <div class="faq-answer"><p>Do thị trường phôi thép biến động theo từng đợt điều chỉnh của nhà máy, báo giá thép thông thường có hiệu lực từ 3 đến 7 ngày kể từ ngày báo giá.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Địa chỉ cửa hàng mua thép xây dựng uy tín tại Đông Hà?</h3>\n  <div class="faq-answer"><p>Siêu Thị VLXD Hoàng Yến tọa lạc tại số 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị (Hotline/Zalo: 0946.575.579 - 0914.127.111).</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Báo Giá Thép Xây Dựng Tại Quảng Trị Mới Nhất | VLXD Hoàng Yến', 'Cập nhật bảng giá thép xây dựng tại Đông Hà, Quảng Trị. Giá thép cuộn D6, D8 và thép cây D10 - D32 Hòa Phát, VAS. Hỗ trợ giao tận chân công trình.', 'thep-xay-dung', 'draft', '2026-09-16 12:15:40', '2026-09-16 12:15:40'),
(36, NULL, 'Các Loại Xi Măng Xây Dựng Phổ Biến & Hướng Dẫn Lựa Chọn Chuẩn Kỹ Thuật', 'cac-loai-xi-mang-xay-dung-pho-bien', 'Tổng hợp các loại xi măng xây dựng phổ biến hiện nay: xi măng PCB30, PCB40, xi măng đa dụng, xi măng xây tô chuyên dụng kèm hướng dẫn lựa chọn cho từng hạng mục công trình.', '\n<p>Xi măng là chất kết dính thủy lực quan trọng bậc nhất trong xây dựng, kết hợp cùng cát, đá, sỏi và nước để tạo nên bê tông kết cấu và vữa xây trát bền vững cho ngôi nhà.</p>\n\n<div class="callout-box">\n  <strong>Tóm tắt phân loại xi măng xây dựng thông dụng (Theo TCVN 6260:2020):</strong><br>\n  - <strong>Xi măng PCB30:</strong> Cường độ nén 28 ngày &ge; 30 N/mm², độ dẻo cao, giữ nước tốt &rarr; Chuyên dùng cho <strong>xây tường, trát tường, cán nền</strong>.<br>\n  - <strong>Xi măng PCB40:</strong> Cường độ nén 28 ngày &ge; 40 N/mm², phát triển cường độ sớm cao &rarr; Chuyên dùng cho <strong>đổ bê tông móng, cột, dầm, sàn</strong>.<br>\n  - <strong>Xi măng đa dụng:</strong> Cân bằng giữa cường độ chịu nén và độ dẻo, linh hoạt cho cả xây tô lẫn đổ bê tông nhà ở dân dụng.<br>\n  - <strong>Quy cách đóng gói:</strong> Bao tiêu chuẩn <strong>50 kg/bao</strong> (20 bao = 1 tấn).\n</div>\n\n<h2>1. Bảng so sánh các chủng loại xi măng poóc lăng hỗn hợp (PCB)</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Chủng Loại Xi Măng</th>\n      <th>Mác Cường Độ (28 ngày)</th>\n      <th>Đặc Tính Nổi Bật</th>\n      <th>Ứng Dụng Khuyến Nghị</th>\n      <th>Tiêu Chuẩn Áp Dụng</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Xi măng PCB30 (Xây tô)</strong></td>\n      <td>&ge; 30 N/mm² (MPa)</td>\n      <td>Độ mịn cao, vữa dẻo mịn bám dính tốt, chống nứt chân chim</td>\n      <td>Xây tường gạch, tô trát trong ngoài, cán nền lát gạch</td>\n      <td>TCVN 6260:2020</td>\n    </tr>\n    <tr>\n      <td><strong>Xi măng PCB40 (Bê tông kết cấu)</strong></td>\n      <td>&ge; 40 N/mm² (MPa)</td>\n      <td>Cường độ chịu nén cao, đóng rắn nhanh, rút ngắn thời gian tháo cốp pha</td>\n      <td>Đổ móng đơn, móng băng, móng cọc, cột, dầm, sàn</td>\n      <td>TCVN 6260:2020</td>\n    </tr>\n    <tr>\n      <td><strong>Xi măng Đa Dụng (PCB40)</strong></td>\n      <td>&ge; 40 N/mm² (MPa)</td>\n      <td>Đa năng, phù hợp cho tất cả các công đoạn từ móng đến hoàn thiện</td>\n      <td>Nhà phố dân dụng, công trình sửa chữa cải tạo</td>\n      <td>TCVN 6260:2020</td>\n    </tr>\n    <tr>\n      <td><strong>Xi măng Bền Sunfat (PC_SR)</strong></td>\n      <td>&ge; 40 N/mm² (MPa)</td>\n      <td>Kháng ion sunfat và clo, chống ăn mòn trong môi trường nước biển / phèn</td>\n      <td>Công trình ven biển, móng cọc ngập mặn, kè biển</td>\n      <td>TCVN 6067:2018</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. Hướng dẫn chọn loại xi măng cho từng giai đoạn xây nhà</h2>\n<h3>Giai đoạn 1: Thi công phần móng và kết cấu chịu lực (Nên dùng PCB40)</h3>\n<p>Móng, cột, dầm, sàn chịu toàn bộ tải trọng của ngôi nhà. Việc sử dụng xi măng mác PCB40 (như Nghi Sơn PCB40, Sông Gianh PCB40, Kim Đỉnh PCB40, Đồng Lâm PCB40) đảm bảo bê tông đạt mác thiết kế (Mác 200, Mác 250, Mác 300) sau 28 ngày bảo dưỡng tiêu chuẩn.</p>\n\n<h3>Giai đoạn 2: Thi công xây tường và tô trát tường (Nên dùng PCB30)</h3>\n<p>Đối với khối xây tường và bề mặt tô trát, cường độ nén không cần quá cao nhưng yêu cầu độ dẻo và khả năng giữ nước tuyệt đối để vữa không bị khô giòn, tránh co ngót gây rạn nứt chân chim bề mặt tường. Sử dụng xi măng xây tô chuyên dụng PCB30 là giải pháp kỹ thuật tối ưu và tiết kiệm chi phí.</p>\n\n<h2>3. Tham khảo danh mục Xi măng tại VLXD Hoàng Yến</h2>\n<p>Quý khách hàng có thể tham khảo thêm danh mục <a href="/xi-mang/">Xi Măng Xây Dựng</a> tại Siêu thị VLXD Hoàng Yến để xem đầy đủ các thương hiệu xi măng Nghi Sơn, Kim Đỉnh, Sông Gianh, Đồng Lâm, Long Sơn.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">PHÂN PHỐI XI MĂNG TẠI QUẢNG TRỊ</div>\n    <h3 class="cta-heading">Cần Tư Vấn & Báo Giá Xi Măng Giao Tận Chân Công Trình?</h3>\n    <p class="cta-description">Siêu thị VLXD Hoàng Yến cung cấp xi măng bao 50kg và xi măng rời, hỗ trợ đội ngũ bốc xếp chuyên nghiệp giao tận nơi tại Đông Hà và toàn tỉnh Quảng Trị.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Báo Giá Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>4. Câu hỏi thường gặp về xi măng xây dựng (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Xi măng PCB30 và PCB40 khác nhau như thế nào?</h3>\n  <div class="faq-answer"><p>Ký hiệu PCB30 biểu thị cường độ nén sau 28 ngày đạt tối thiểu 30 N/mm², tối ưu cho xây trát; PCB40 đạt tối thiểu 40 N/mm², cường độ chịu lực cao hơn, chuyên dùng cho bê tông móng, cột, dầm, sàn.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. 1 bao xi măng xây dựng nặng bao nhiêu kg?</h3>\n  <div class="faq-answer"><p>Quy cách đóng bao tiêu chuẩn của hầu hết các nhà máy xi măng tại Việt Nam là 50 kg/bao.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. 1 tấn xi măng có bao nhiêu bao?</h3>\n  <div class="faq-answer"><p>1 tấn (1.000 kg) xi măng tương đương đúng 20 bao 50kg (1.000 / 50 = 20 bao).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. Đổ bê tông nhà dân dụng nên dùng xi măng mác bao nhiêu?</h3>\n  <div class="faq-answer"><p>Nên sử dụng xi măng mác PCB40 để đảm bảo bê tông phát triển cường độ nén nhanh và đạt độ cứng chắc kết cấu móng dầm sàn lâu dài.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. Hạn sử dụng của xi măng là bao lâu kể từ ngày sản xuất?</h3>\n  <div class="faq-answer"><p>Xi măng bao duy trì hoạt tính tốt nhất trong vòng 60 ngày kể từ ngày sản xuất in trên vỏ bao. Sau thời gian này trong môi trường độ ẩm cao, phẩm chất xi măng có thể suy giảm dần.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Xi măng bị vón cục cứng có dùng để đổ bê tông được không?</h3>\n  <div class="faq-answer"><p>Tuyệt đối không sử dụng xi măng đã bị vón cục cứng cho các kết cấu chịu lực chính (móng, cột, dầm, sàn) vì các hạt clinker đã thủy hóa mất liên kết chịu lực.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Tỷ lệ trộn vữa xây trát mác 75 thông thường là bao nhiêu?</h3>\n  <div class="faq-answer"><p>Cấp phối thực tế thông thường ngoài công trường cho 1 bao xi măng 50kg (PCB30) trộn với khoảng 8 đến 9 thùng cát 18 lít để tạo vữa mác 75 dẻo mịn.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Cách xếp bảo quản xi măng tại công trường tránh ẩm?</h3>\n  <div class="faq-answer"><p>Cần kê xi măng trên pallet gỗ cách mặt đất tối thiểu 15–20cm, cách tường 20cm, trùm bạt kín và không xếp chồng cao quá 10 bao.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Các thương hiệu xi măng phổ biến tại Quảng Trị gồm những hãng nào?</h3>\n  <div class="faq-answer"><p>Tại Quảng Trị, các thương hiệu được tin dùng hàng đầu gồm có: Xi măng Nghi Sơn, Xi măng Kim Đỉnh, Xi măng Sông Gianh, Xi măng Đồng Lâm, Xi măng Long Sơn, Vicem Hoàng Mai.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua xi măng chính hãng tại Đông Hà Quảng Trị ở đâu?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể liên hệ Siêu thị VLXD Hoàng Yến tại 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị (Hotline/Zalo: 0946.575.579) để nhận báo giá cập nhật mới nhất.</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Các Loại Xi Măng Xây Dựng Phổ Biến Nhất | VLXD Hoàng Yến', 'Tìm hiểu các loại xi măng xây dựng phổ biến: PCB30, PCB40, xi măng xây tô, xi măng đổ bê tông. Tiêu chuẩn TCVN 6260 và hướng dẫn chọn mác xi măng xây nhà.', 'xi-mang', 'draft', '2026-09-16 12:16:21', '2026-09-16 12:16:21'),
(37, NULL, 'Phân Biệt Xi Măng PCB30 Và PCB40: Tiêu Chuẩn & Khi Nào Nên Dùng', 'phan-biet-xi-mang-pcb30-va-pcb40', 'So sánh chi tiết xi măng PCB30 và PCB40: Khác biệt về cường độ chịu nén, độ mịn, thời gian đóng rắn, ứng dụng và kinh nghiệm chọn mác xi măng xây nhà tối ưu.', '\n<p>Trên bao bì các loại xi măng xây dựng hiện nay, hai ký hiệu phổ biến nhất mà bạn thường thấy là <strong>PCB30</strong> và <strong>PCB40</strong>. Việc hiểu rõ sự khác biệt giữa hai mác xi măng này giúp bạn sử dụng đúng công năng và tiết kiệm đáng kể ngân sách xây nhà.</p>\n\n<div class="callout-box">\n  <strong>Khác biệt cốt lõi giữa PCB30 và PCB40 (Theo TCVN 6260:2020):</strong><br>\n  - <strong>PCB30:</strong> Cường độ nén sau 28 ngày &ge; <strong>30 MPa</strong>. Độ mịn cao, dẻo vữa, giữ nước tốt &rarr; Tối ưu cho <strong>xây tường, tô trát hoàn thiện</strong>.<br>\n  - <strong>PCB40:</strong> Cường độ nén sau 28 ngày &ge; <strong>40 MPa</strong> (cao hơn 33%). Đóng rắn nhanh &rarr; Tối ưu cho <strong>đổ bê tông kết cấu móng, cột, dầm, sàn</strong>.\n</div>\n\n<h2>1. Bảng so sánh chỉ tiêu kỹ thuật giữa xi măng PCB30 và PCB40</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Tiêu Chí Kỹ Thuật</th>\n      <th>Xi Măng PCB30</th>\n      <th>Xi Măng PCB40</th>\n      <th>Ý Nghĩa Kỹ Thuật</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Cường độ nén sau 3 ngày</strong></td>\n      <td>&ge; 14 MPa (N/mm²)</td>\n      <td>&ge; 18 MPa (N/mm²)</td>\n      <td>Độ cứng ban đầu của bê tông/vữa</td>\n    </tr>\n    <tr>\n      <td><strong>Cường độ nén sau 28 ngày</strong></td>\n      <td>&ge; 30 MPa (N/mm²)</td>\n      <td>&ge; 40 MPa (N/mm²)</td>\n      <td>Cường độ chịu nén chuẩn kết cấu</td>\n    </tr>\n    <tr>\n      <td><strong>Độ mịn bề mặt riêng</strong></td>\n      <td>Rất mịn (&ge; 2800 cm²/g)</td>\n      <td>Tiêu chuẩn (&ge; 2800 cm²/g)</td>\n      <td>Độ dẻo và độ bám dính của vữa</td>\n    </tr>\n    <tr>\n      <td><strong>Thời gian đông kết bắt đầu</strong></td>\n      <td>&ge; 45 phút</td>\n      <td>&ge; 45 phút</td>\n      <td>Đảm bảo thời gian thi công nhào trộn</td>\n    </tr>\n    <tr>\n      <td><strong>Độ dẻo và giữ nước</strong></td>\n      <td>Rất cao, khó mất nước</td>\n      <td>Trung bình khá</td>\n      <td>Chống nứt chân chim bề mặt tường</td>\n    </tr>\n    <tr>\n      <td><strong>Đơn giá thành</strong></td>\n      <td>Tiết kiệm hơn PCB40</td>\n      <td>Cao hơn PCB30 khoảng 5 - 10%</td>\n      <td>Chi phí trên mỗi bao 50kg</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. Khi nào nên dùng xi măng PCB30 và khi nào nên dùng PCB40?</h2>\n<h3>Trường hợp nên dùng xi măng PCB30:</h3>\n<ul>\n  <li>Xây tường gạch ống, gạch đặc, gạch tuynel.</li>\n  <li>Trát (tô) tường nội thất và ngoại thất.</li>\n  <li>Láng nền, cán phẳng sàn trước khi lát gạch men hoặc ốp đá.</li>\n</ul>\n\n<h3>Trường hợp bắt buộc nên dùng xi măng PCB40:</h3>\n<ul>\n  <li>Đổ bê tông móng đơn, móng băng, móng bè, đài cọc.</li>\n  <li>Đổ bê tông cột chịu lực, dầm sàn các tầng lầu và sàn mái.</li>\n  <li>Đúc các cấu kiện bê tông đúc sẵn, lanh tô gối chịu tải nặng.</li>\n</ul>\n\n<h2>3. Tham khảo danh mục Xi măng tại VLXD Hoàng Yến</h2>\n<p>Xem thêm bài viết tổng quan <a href="/tin-tuc/cac-loai-xi-mang-xay-dung-pho-bien/">Các Loại Xi Măng Xây Dựng Phổ Biến</a> hoặc truy cập danh mục <a href="/xi-mang/">Xi Măng</a> tại VLXD Hoàng Yến.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">TƯ VẤN VẬT TƯ CHÍNH XÁC</div>\n    <h3 class="cta-heading">Cần Tư Vấn Cấp Phối Xi Măng PCB30 & PCB40?</h3>\n    <p class="cta-description">Siêu thị VLXD Hoàng Yến phân phối đầy đủ các dòng xi măng PCB30 và PCB40 từ Nghi Sơn, Sông Gianh, Kim Đỉnh, Đồng Lâm tại Quảng Trị.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Báo Giá Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>4. Câu hỏi thường gặp về xi măng PCB30 và PCB40 (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Chữ "PCB" trong ký hiệu xi măng viết tắt của từ gì?</h3>\n  <div class="faq-answer"><p>Ký hiệu "PCB" viết tắt của cụm từ tiếng Anh "Portland Cement Blended", nghĩa là Xi măng Poóc lăng Hỗn hợp theo Tiêu chuẩn Quốc gia TCVN 6260.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. Dùng xi măng PCB40 để xây trát tường có tốt hơn PCB30 không?</h3>\n  <div class="faq-answer"><p>Không hẳn. Xi măng PCB40 phát triển cường độ nhanh và sinh nhiệt thủy hóa cao hơn, nếu bảo dưỡng tưới nước không kỹ khi trát tường rất dễ dẫn đến co ngót nứt chân chim. Xi măng PCB30 giữ nước tốt hơn nên tối ưu hơn cho công tác xây tô.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. Dùng xi măng PCB30 để đổ bê tông sàn nhà có an toàn không?</h3>\n  <div class="faq-answer"><p>Vẫn được nếu tăng lượng xi măng theo đúng bảng cấp phối thiết kế, tuy nhiên bê tông sẽ phát triển cường độ chậm hơn, đòi hỏi thời gian dưỡng hộ và giữ cốp pha lâu hơn so với PCB40.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. 1 bao xi măng PCB30 và PCB40 có khối lượng bằng nhau không?</h3>\n  <div class="faq-answer"><p>Có. Cả hai loại đều đóng gói theo quy chuẩn chuẩn quốc gia là 50 kg/bao.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. Giá xi măng PCB40 chênh lệch bao nhiêu so với PCB30?</h3>\n  <div class="faq-answer"><p>Thông thường 1 bao xi măng PCB40 chênh lệch cao hơn PCB30 khoảng 3.000đ đến 7.000đ/bao tùy theo từng thương hiệu nhà sản xuất.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Xi măng đa dụng thuộc mác PCB30 hay PCB40?</h3>\n  <div class="faq-answer"><p>Đa số các dòng xi măng đa dụng thương hiệu lớn hiện nay (như Nghi Sơn đa dụng, Sông Gianh đa dụng) đều đạt tiêu chuẩn cường độ mác PCB40.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Thời gian tháo cốp pha khi dùng xi măng PCB40 là bao lâu?</h3>\n  <div class="faq-answer"><p>Đối với cốp pha dầm sàn nhà dân dụng khi dùng xi măng PCB40 và bảo dưỡng đúng cách, thời gian tháo dỡ cốp pha an toàn thông thường từ 21 đến 28 ngày (đối với cốp pha thành cột có thể tháo sau 24 - 48 giờ).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Nhận biết xi măng PCB30 và PCB40 trên vỏ bao như thế nào?</h3>\n  <div class="faq-answer"><p>Ký hiệu "PCB30" hoặc "PCB40" luôn được in to rõ ràng ngay chính giữa mặt trước của vỏ bao cùng logo thương hiệu nhà máy.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Hạn sử dụng của 2 loại xi măng này có khác nhau không?</h3>\n  <div class="faq-answer"><p>Cả PCB30 và PCB40 đều có hạn sử dụng tối ưu trong vòng 60 ngày kể từ ngày sản xuất in trên vỏ bao.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua xi măng PCB30, PCB40 tại Đông Hà Quảng Trị ở đâu uy tín?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể mua tại Siêu thị VLXD Hoàng Yến - 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị (Hotline/Zalo: 0946.575.579).</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Phân Biệt Xi Măng PCB30 Và PCB40 Chi Tiết | VLXD Hoàng Yến', 'So sánh xi măng PCB30 và PCB40 theo TCVN 6260:2020. Cường độ nén 28 ngày, độ dẻo vữa và hướng dẫn chọn xi măng đổ bê tông hoặc xây trát tường tối ưu.', 'xi-mang', 'draft', '2026-09-16 12:16:22', '2026-09-16 12:16:22'),
(38, NULL, '1 Bao Xi Măng Xây Được Bao Nhiêu M2 Tường? Định Mức Chuẩn', '1-bao-xi-mang-xay-trat-duoc-bao-nhieu-m2', '1 bao xi măng 50kg xây được bao nhiêu m2 tường 10, tường 20? 1 bao xi măng trát được bao nhiêu m2 tường dày 1,5cm? Bảng định mức chi tiết kèm ví dụ dự toán.', '\n<p>Biết được 1 bao xi măng 50kg xây hoặc trát được bao nhiêu mét vuông tường là cơ sở quan trọng giúp gia chủ tự tính toán số lượng bao xi măng cần mua cho ngôi nhà, tránh mua thiếu gián đoạn thi công hoặc mua dư thừa lãng phí.</p>\n\n<div class="callout-box">\n  <strong>Định mức tham khảo thực tế cho 1 bao xi măng 50kg (Vữa Mác 75 tiêu chuẩn):</strong><br>\n  - <strong>Xây tường 10 (tường dày 110mm):</strong> 1 bao xi măng xây được khoảng <strong>3,5 đến 4,0 m² tường</strong>.<br>\n  - <strong>Xây tường 20 (tường dày 220mm):</strong> 1 bao xi măng xây được khoảng <strong>1,8 đến 2,0 m² tường</strong>.<br>\n  - <strong>Trát tường dày 1,5cm (15mm):</strong> 1 bao xi măng trát được khoảng <strong>4,0 đến 5,0 m² bề mặt tường</strong>.\n</div>\n\n<h2>1. Bảng định mức tiêu hao xi măng cho 1m2 tường xây và trát</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Hạng Mục Thi Công</th>\n      <th>Chiều Dày Khối Xây / Trát</th>\n      <th>Lượng Xi Măng Tiêu Hao Cho 1m²</th>\n      <th>1 Bao 50kg Thi Công Được</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Xây tường 10 (Gạch tuynel ống)</strong></td>\n      <td>110 mm</td>\n      <td>12 - 14 kg xi măng/m²</td>\n      <td><strong>~ 3,5 - 4,0 m² tường</strong></td>\n    </tr>\n    <tr>\n      <td><strong>Xây tường 20 (Gạch tuynel ống)</strong></td>\n      <td>220 mm</td>\n      <td>25 - 28 kg xi măng/m²</td>\n      <td><strong>~ 1,8 - 2,0 m² tường</strong></td>\n    </tr>\n    <tr>\n      <td><strong>Trát tường dày 1,5cm (Mác 75)</strong></td>\n      <td>15 mm</td>\n      <td>10 - 12 kg xi măng/m²</td>\n      <td><strong>~ 4,2 - 5,0 m² trát</strong></td>\n    </tr>\n    <tr>\n      <td><strong>Trát tường dày 2,0cm (Mác 75)</strong></td>\n      <td>20 mm</td>\n      <td>14 - 16 kg xi măng/m²</td>\n      <td><strong>~ 3,1 - 3,5 m² trát</strong></td>\n    </tr>\n    <tr>\n      <td><strong>Cán nền dày 3,0cm (Mác 75)</strong></td>\n      <td>30 mm</td>\n      <td>20 - 22 kg xi măng/m²</td>\n      <td><strong>~ 2,3 - 2,5 m² cán nền</strong></td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>2. Ví dụ tính toán số bao xi măng cần cho bức tường 50m2</h2>\n<p><strong>Bài toán:</strong> Bạn cần xây mới và trát hoàn thiện 2 mặt cho một bức tường 10 có diện tích 50 m² (chiều dài 12,5m, chiều cao 4m). Hãy tính số bao xi măng 50kg cần mua?</p>\n<ul>\n  <li><strong>Xi măng để xây tường 10:</strong> <code>50 m² × 13 kg/m² = 650 kg xi măng</code>.</li>\n  <li><strong>Xi măng để trát 2 mặt (tổng diện tích trát = 50 × 2 = 100 m²):</strong> <code>100 m² × 11 kg/m² = 1.100 kg xi măng</code>.</li>\n  <li><strong>Tổng khối lượng xi măng:</strong> <code>650 + 1.100 = 1.750 kg</code>.</li>\n  <li><strong>Số bao xi măng 50kg:</strong> <code>1.750 / 50 = 35 bao</code>.</li>\n  <li><strong>Cộng hao hụt vữa rơi vãi 5%:</strong> Cần đặt mua khoảng <strong>37 bao xi măng</strong>.</li>\n</ul>\n\n<h2>3. Tham khảo danh mục Xi măng tại VLXD Hoàng Yến</h2>\n<p>Quý khách hàng có thể xem thêm bài viết <a href="/tin-tuc/cac-loai-xi-mang-xay-dung-pho-bien/">Các Loại Xi Măng Xây Dựng Phổ Biến</a> hoặc truy cập danh mục <a href="/xi-mang/">Xi Măng</a> tại Siêu thị VLXD Hoàng Yến.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">DỰ TOÁN VẬT TƯ XÂY DỰNG</div>\n    <h3 class="cta-heading">Cần Tính Toán Khối Lượng Xi Măng Cho Công Trình?</h3>\n    <p class="cta-description">Gửi diện tích xây dựng nhà bạn cho Siêu thị VLXD Hoàng Yến để được tư vấn bóc tách khối lượng xi măng, gạch, cát chính xác nhất.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Zalo Tư Vấn</a>\n    </div>\n  </div>\n</div>\n\n<h2>4. Câu hỏi thường gặp về định mức xi măng xây trát (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. 1 bao xi măng 50kg xây được bao nhiêu mét vuông tường 10?</h3>\n  <div class="faq-answer"><p>Trung bình 1 bao xi măng 50kg vữa mác 75 xây được khoảng 3,5 đến 4,0 m² tường 10 (dày 110mm).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. 1 bao xi măng 50kg xây được bao nhiêu mét vuông tường 20?</h3>\n  <div class="faq-answer"><p>Đối với tường đôi 20 (dày 220mm), 1 bao xi măng xây được khoảng 1,8 đến 2,0 m² tường.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. 1 bao xi măng trát được bao nhiêu m2 tường?</h3>\n  <div class="faq-answer"><p>Với chiều dày lớp trát tiêu chuẩn 1,5cm (15mm), 1 bao xi măng trát được khoảng 4 đến 5 m² bề mặt tường.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. 1m2 tường 10 cần bao nhiêu viên gạch và bao nhiêu xi măng?</h3>\n  <div class="faq-answer"><p>1m² tường 10 cần khoảng 65 đến 70 viên gạch tuynel tiêu chuẩn và khoảng 12 đến 14 kg xi măng (cùng 0,04 m³ cát xây).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. 1m2 tường 20 cần bao nhiêu viên gạch và bao nhiêu xi măng?</h3>\n  <div class="faq-answer"><p>1m² tường 20 cần khoảng 130 đến 140 viên gạch tuynel tiêu chuẩn và khoảng 25 đến 28 kg xi măng (cùng 0,08 m³ cát xây).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Chiều dày lớp vữa trát tường chuẩn kỹ thuật là bao nhiêu mm?</h3>\n  <div class="faq-answer"><p>Theo TCVN về thi công và nghiệm thu công tác hoàn thiện, chiều dày lớp vữa trát tường thông thường dao động từ 12mm đến 20mm (trung bình 15mm).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Tỷ lệ hao hụt vữa xây trát trong thực tế là bao nhiêu?</h3>\n  <div class="faq-answer"><p>Định mức hao hụt rơi vãi thực tế của vữa xây trát tại công trường thường dao động từ 3% đến 5%.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Xây tường bằng cát mịn hay cát vàng tốt hơn?</h3>\n  <div class="faq-answer"><p>Xây tường nên sử dụng cát hạt trung (mô đun độ lớn từ 1,5 đến 2,0) sạch không lẫn bùn sét để vữa bám dính tốt; công tác trát tường có thể dùng cát mịn hơn để bề mặt tường láng mịn.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Có nên trộn vữa quá nhiều xi măng (vữa quá già) khi trát tường không?</h3>\n  <div class="faq-answer"><p>Không nên. Vữa trát quá nhiều xi măng (vữa già mác) sẽ co ngót rất mạnh khi đóng rắn, dẫn đến hiện tượng nứt chân chim chằng chịt trên bề mặt tường sau khi khô.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Mua xi măng xây tô tại Đông Hà Quảng Trị ở đâu?</h3>\n  <div class="faq-answer"><p>Quý khách hàng có thể liên hệ Siêu thị VLXD Hoàng Yến tại 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị (Hotline/Zalo: 0946.575.579).</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', '1 Bao Xi Măng Xây Được Bao Nhiêu M2 Tường? | VLXD Hoàng Yến', '1 bao xi măng 50kg xây được khoảng 3,5 - 4 m2 tường 10 và trát được khoảng 4 - 5 m2 tường dày 1,5cm. Bảng tính định mức vữa xây tô chi tiết chuẩn kỹ thuật.', 'xi-mang', 'draft', '2026-09-16 12:16:22', '2026-09-16 12:16:22'),
(39, NULL, 'Bảng Báo Giá Xi Măng Tại Quảng Trị Mới Nhất Hôm Nay', 'gia-xi-mang-tai-quang-tri', 'Bảng báo giá xi măng Nghi Sơn, Kim Đỉnh, Sông Gianh, Đồng Lâm, Long Sơn tại Đông Hà, Quảng Trị. Đơn giá xi măng bao 50kg và xi măng rời theo tấn cho công trình.', '\n<p>Xi măng là vật tư chiếm tỷ trọng chi phí nền tảng trong toàn bộ giai đoạn xây thô và hoàn thiện ngôi nhà. Giá xi măng trên thị trường biến động theo giá clinker nhà máy, chi phí vận tải và khối lượng đơn hàng.</p>\n\n<div class="callout-box">\n  <strong>Lưu ý về đơn giá xi măng tại Quảng Trị:</strong><br>\n  Đơn giá xi măng thực tế phụ thuộc vào thương hiệu (Nghi Sơn, Sông Gianh, Kim Đỉnh, Đồng Lâm, Long Sơn), loại mác (PCB30 xây tô hay PCB40 bê tông), số lượng đặt mua (mua bao lẻ hay mua xe tải theo tấn) và địa điểm giao nhận. Quý khách vui lòng liên hệ Hotline 0946.575.579 để nhận báo giá hiện hành.\n</div>\n\n<h2>1. Các thương hiệu xi măng xây dựng được tin dùng nhất tại Quảng Trị</h2>\n<ul>\n  <li><strong>Xi măng Nghi Sơn:</strong> Thương hiệu liên doanh Nhật Bản chất lượng cao, độ dẻo và cường độ ổn định vượt trội, chuyên dụng cho các công trình đòi hỏi kết cấu khắt khe.</li>\n  <li><strong>Xi măng Sông Gianh:</strong> Thương hiệu truyền thống được tin dùng rộng rãi tại miền Trung, vữa dẻo mịn, phát triển cường độ tốt.</li>\n  <li><strong>Xi măng Kim Đỉnh / Đồng Lâm:</strong> Lựa chọn kinh tế tối ưu cho nhà ở dân dụng với cường độ ổn định và giá thành hợp lý.</li>\n  <li><strong>Xi măng Long Sơn / Vicem Hoàng Mai:</strong> Đáp ứng đầy đủ các tiêu chuẩn TCVN 6260 cho công trình dân dụng và dự án.</li>\n</ul>\n\n<h2>2. Các yếu tố ảnh hưởng trực tiếp đến giá xi măng</h2>\n<ol>\n  <li><strong>Thương hiệu và mác xi măng:</strong> Mác PCB40 đổ bê tông thường cao hơn mác PCB30 xây tô khoảng 3.000 - 7.000 đ/bao.</li>\n  <li><strong>Hình thức mua hàng:</strong> Mua theo tấn (20 bao/tấn) hoặc mua số lượng lớn cho toàn bộ công trình luôn có chiết khấu tốt hơn mua lẻ vài bao.</li>\n  <li><strong>Chi phí cước vận chuyển & bốc xếp:</strong> Vận chuyển từ kho 299 Lê Duẩn, Đông Hà đến các địa bàn lân cận như Cam Lộ, Triệu Phong, Gio Linh, Cồn Tiên, Cửa Việt.</li>\n</ol>\n\n<h2>3. Tham khảo danh mục Xi măng tại VLXD Hoàng Yến</h2>\n<p>Quý khách hàng có thể xem thông tin chi tiết các dòng sản phẩm tại danh mục <a href="/xi-mang/">Xi Măng Xây Dựng</a> của Siêu thị VLXD Hoàng Yến.</p>\n\n<div class="article-cta-box">\n  <div class="cta-inner">\n    <div class="cta-badge">BÁO GIÁ XUẤT KHO</div>\n    <h3 class="cta-heading">Nhận Báo Giá Xi Măng Hôm Nay Tại Quảng Trị</h3>\n    <p class="cta-description">Gửi số lượng bao dự kiến và địa điểm công trình để Siêu thị VLXD Hoàng Yến báo giá tốt nhất và sắp xếp xe giao hàng tận chân công trình.</p>\n    <div class="cta-buttons-group">\n      <a href="tel:0946575579" class="btn btn-cta-primary">Hotline: 0946.575.579</a>\n      <a href="https://zalo.me/0946575579" target="_blank" class="btn btn-cta-secondary">Báo Giá Zalo</a>\n    </div>\n  </div>\n</div>\n\n<h2>4. Câu hỏi thường gặp về giá xi măng tại Quảng Trị (FAQ)</h2>\n\n<div class="faq-item">\n  <h3 class="faq-question">1. Giá xi măng tại Quảng Trị tính theo bao 50kg hay theo tấn?</h3>\n  <div class="faq-answer"><p>Cả hai hình thức: Mua lẻ tính theo giá từng bao 50kg; mua công trình tính theo giá tấn (1 tấn = 20 bao 50kg).</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">2. VLXD Hoàng Yến có hỗ trợ bốc xếp xi măng xuống tận chân công trình không?</h3>\n  <div class="faq-answer"><p>Có. Đội xe tải của chúng tôi có nhân viên hỗ trợ giao hàng và bốc dỡ xi măng xếp gọn gàng vào kho công trình của khách hàng.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">3. Mua xi măng số lượng bao nhiêu thì được giao hàng tận nơi?</h3>\n  <div class="faq-answer"><p>Chúng tôi hỗ trợ giao tận nơi cho các đơn hàng từ 10 bao trở lên tại khu vực TP. Đông Hà và các đơn hàng từ 1 tấn trở lên tại các huyện lân cận trong tỉnh Quảng Trị.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">4. Xi măng PCB30 và PCB40 loại nào giá cao hơn?</h3>\n  <div class="faq-answer"><p>Xi măng PCB40 thường có giá cao hơn PCB30 khoảng vài nghìn đồng mỗi bao do tỷ lệ clinker cao hơn và cường độ chịu nén lớn hơn.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">5. Có được đổi trả nếu bao xi măng bị rách thủng do vận chuyển không?</h3>\n  <div class="faq-answer"><p>Nếu bao xi măng bị rách thủng trong quá trình vận chuyển của Hoàng Yến, chúng tôi cam kết đổi bao nguyên vẹn ngay cho quý khách khi nhận hàng.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">6. Giá xi măng có bao gồm hóa đơn VAT không?</h3>\n  <div class="faq-answer"><p>Siêu thị VLXD Hoàng Yến hỗ trợ xuất đầy đủ hóa đơn giá trị gia tăng (VAT) hợp lệ theo đúng quy định pháp luật.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">7. Xây 1 ngôi nhà 2 tầng 100m2 sàn cần khoảng bao nhiêu tấn xi măng?</h3>\n  <div class="faq-answer"><p>Thông thường một ngôi nhà 2 tầng tổng diện tích sàn 200m2 tiêu hao khoảng 15 đến 20 tấn xi măng (khoảng 300 đến 400 bao 50kg) cho toàn bộ phần thô và trát hoàn thiện.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">8. Thời gian giao xi măng sau khi đặt hàng là bao lâu?</h3>\n  <div class="faq-answer"><p>Trong khu vực nội thành Đông Hà, hàng thường được giao trong vòng 2 đến 4 giờ kể từ khi xác nhận đơn hàng.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">9. Báo giá xi măng có hiệu lực trong bao lâu?</h3>\n  <div class="faq-answer"><p>Báo giá xi măng thông thường ổn định theo từng tháng hoặc có hiệu lực từ 7 đến 15 ngày kể từ ngày báo giá.</p></div>\n</div>\n\n<div class="faq-item">\n  <h3 class="faq-question">10. Địa chỉ mua xi măng uy tín tại Đông Hà Quảng Trị?</h3>\n  <div class="faq-answer"><p>Siêu thị VLXD Hoàng Yến tọa lạc tại số 299 Lê Duẩn, Phường Đông Hà, Tỉnh Quảng Trị (Hotline/Zalo: 0946.575.579 - 0914.127.111).</p></div>\n</div>\n', 'https://vlxdhoangyen.com/wp-content/uploads/2025/07/VAT-LIEU-XAY-DUNG-1920-x-731-px-4.png', 'Báo Giá Xi Măng Tại Quảng Trị Mới Nhất | VLXD Hoàng Yến', 'Bảng giá xi măng Nghi Sơn, Kim Đỉnh, Sông Gianh, Đồng Lâm PCB30 & PCB40 tại Đông Hà, Quảng Trị. Giá xi măng bao 50kg và theo tấn giao tận chân công trình.', 'xi-mang', 'draft', '2026-09-16 12:16:22', '2026-09-16 12:16:22');
